CREATE FUNCTION [Reference].[GetFullAddressByTown]
(
    @Id int
)
RETURNS NVARCHAR(159)
BEGIN
	DECLARE @FullAddress NVARCHAR(159)

    SELECT @FullAddress = CONCAT(
                                [AT].[Name], ', ', 
                                [AC].[Name], ', ', 
                                [AS].[Name], ', ',
                                [ACD].[Acronym], ', ', 
                                [ACO].[Name])
    FROM
        [Static].[AddressTown] AS [AT]
        LEFT JOIN [Static].[AddressCity] AS [AC] ON [AC].[Id] = [AT].[AddressCityId]
        LEFT JOIN [Static].[AddressState] AS [AS] ON [AS].[Id] = [AC].[AddressStateId]
        LEFT JOIN [Static].[AddressCountryDivision] AS [ACD] ON [ACD].[Id] = [AS].[AddressCountryDivisionId]
        LEFT JOIN [Static].[AddressCountry] AS [ACO] ON [ACO].[Id] = [ACD].[AddressCountryId]
        LEFT JOIN [Static].[AddressRegionDivision] AS [ARD] ON [ARD].[Id] = [ACO].[AddressRegionDivisionId]
        LEFT JOIN [Static].[AddressRegion] AS [AR] ON [AR].[Id] = [ARD].[AddressRegionId]
    WHERE 
        [AT].[Id] = @Id;

	RETURN @FullAddress;
END
GO
