                         [Transaction].GroupPolicy.BranchCode, [Transaction].GroupPolicy.BranchName, [Transaction].GroupPolicy.ProviderPolicyNo, [Transaction].GroupPolicy.EndorsementNo, [Transaction].GroupPolicy.TerminationDate, 
                         [Transaction].GroupPolicy.EffectiveDate, [Transaction].GroupPolicy.IssueDate, [Transaction].GroupPolicy.Remarks, [Transaction].GroupPolicy.TotalPremium, [Transaction].GroupPolicy.TotalCoverage, 
                         [Transaction].GroupPolicy.TotalPaid, [Transaction].PolicyPremiums.BasicPremium, [Transaction].PolicyPremiums.BasicPremiumCommission, [Transaction].PolicyPremiums.DJDPatricioMarkup, 
                         [Transaction].PolicyPremiums.PartnerMarkup, [Transaction].PolicyPremiums.Discount, [Transaction].PolicyPremiums.Taxes, [Transaction].PolicyPremiums.DST, [Transaction].PolicyPremiums.VAT, 
                         [Transaction].PolicyPremiums.LGT, [Transaction].PolicyPremiums.PT, [Transaction].PolicyPremiums.FST, [Transaction].PolicyPremiums.NotarialFee, [Transaction].PolicyPremiums.Others, 
                         [Transaction].PolicyPremiums.Remarks AS PremiumsRemarks, [Transaction].GroupPolicy.PartnersId, [Transaction].GroupPolicy.PlatformsId, [Transaction].GroupPolicy.IssueStatus, 
                         [Transaction].GroupPolicy.PolicyBookingStatusId, [Transaction].GroupPolicy.CocStatusId, [Transaction].GroupPolicy.PaymentStatusId, [Transaction].GroupPolicy.ClaimsStatusId, [Transaction].GroupPolicy.AgentsId, 
                         [Transaction].GroupPolicy.SubAgentsId, [Transaction].GroupPolicy.ApproversId, [Transaction].GroupPolicy.PromoManagersId, [Transaction].GroupPolicy.SalesManagersId, [Transaction].GroupPolicy.PromoOfficersId, 
                         [Transaction].GroupPolicy.ProductsId, Reference.Products.ProductCategoryId, [Transaction].GroupPolicy.ProvidersId, [Transaction].GroupPolicy.DistributionChannelId, [Transaction].GroupPolicy.PaymentOptionId, 
                         [Transaction].GroupPolicy.AccountTypeId, [Transaction].GroupPolicy.CreatedBy, [Transaction].GroupPolicy.CreatedDateTime, [Transaction].GroupPolicy.ModifiedBy, [Transaction].GroupPolicy.ModifiedDateTime
FROM            [Transaction].GroupPolicy LEFT OUTER JOIN
