                         Static.PaymentStatus ON Static.PaymentStatus.Id = [Transaction].GroupPolicy.PaymentStatusId LEFT OUTER JOIN
                         Static.ClaimsStatus ON Static.ClaimsStatus.Id = [Transaction].GroupPolicy.ClaimsStatusId LEFT OUTER JOIN
                         Reference.Agents ON Reference.Agents.Id = [Transaction].GroupPolicy.AgentsId LEFT OUTER JOIN
                         Reference.SubAgents ON Reference.SubAgents.Id = [Transaction].GroupPolicy.SubAgentsId LEFT OUTER JOIN
                         Reference.Approvers ON Reference.Approvers.Id = [Transaction].GroupPolicy.ApproversId LEFT OUTER JOIN
