CREATE VIEW [dbo].[AttachmentsView]
AS
SELECT        [Transaction].Attachments.Id, [Transaction].Attachments.ReferenceId, Static.AttachmentType.Name AS AttachmentType, 
                         CASE WHEN [Transaction].Attachments.AttachmentTypeId = 1 THEN [Transaction].IndividualPolicy.Id WHEN [Transaction].Attachments.AttachmentTypeId = 2 THEN [Transaction].PartnerPolicy.Id WHEN [Transaction].Attachments.AttachmentTypeId
                          IN (3, 4) 
                         THEN [Transaction].GroupPolicy.Id WHEN [Transaction].Attachments.AttachmentTypeId = 5 THEN CASE WHEN [Transaction].PolicyPayments.PolicyTypeId = 1 THEN IndividualPolicy_1.Id WHEN [Transaction].PolicyPayments.PolicyTypeId
                          = 2 THEN PartnerPolicy_1.Id WHEN [Transaction].PolicyPayments.PolicyTypeId = 3 THEN GroupPolicy_2.Id ELSE NULL END ELSE NULL END AS PolicyId, 
                         CASE WHEN [Transaction].Attachments.AttachmentTypeId = 1 THEN [Transaction].IndividualPolicy.ReferenceNumber WHEN [Transaction].Attachments.AttachmentTypeId = 2 THEN [Transaction].PartnerPolicy.ReferenceNumber WHEN
                          [Transaction].Attachments.AttachmentTypeId IN (3, 4) 
                         THEN [Transaction].GroupPolicy.ReferenceNumber WHEN [Transaction].Attachments.AttachmentTypeId = 5 THEN CASE WHEN [Transaction].PolicyPayments.PolicyTypeId = 1 THEN IndividualPolicy_1.ReferenceNumber WHEN [Transaction].PolicyPayments.PolicyTypeId
                          = 2 THEN PartnerPolicy_1.ReferenceNumber WHEN [Transaction].PolicyPayments.PolicyTypeId = 3 THEN GroupPolicy_2.ReferenceNumber ELSE NULL END ELSE NULL END AS PolicyReferenceNumber, 
                         CASE WHEN [Transaction].Attachments.AttachmentTypeId = 1 THEN [Transaction].IndividualPolicy.COCNumber WHEN [Transaction].Attachments.AttachmentTypeId = 2 THEN [Transaction].PartnerPolicy.COCNumber WHEN [Transaction].Attachments.AttachmentTypeId
                          IN (3, 4) 
                         THEN [Transaction].GroupPolicy.COCNumber WHEN [Transaction].Attachments.AttachmentTypeId = 5 THEN CASE WHEN [Transaction].PolicyPayments.PolicyTypeId = 1 THEN IndividualPolicy_1.COCNumber WHEN [Transaction].PolicyPayments.PolicyTypeId
                          = 2 THEN PartnerPolicy_1.COCNumber WHEN [Transaction].PolicyPayments.PolicyTypeId = 3 THEN GroupPolicy_2.COCNumber ELSE NULL END ELSE NULL END AS PolicyCOCNumber, [Transaction].Attachments.ContentType, 
                         [Transaction].Attachments.FileName, [Transaction].Attachments.Attachment, [Transaction].Attachments.AttachmentTypeId, [Transaction].Attachments.CreatedBy, [Transaction].Attachments.CreatedDateTime, 
                         [Transaction].Attachments.ModifiedBy, [Transaction].Attachments.ModifiedDateTime
FROM            [Transaction].Attachments LEFT OUTER JOIN
                         Static.AttachmentType ON Static.AttachmentType.Id = [Transaction].Attachments.AttachmentTypeId LEFT OUTER JOIN
                         [Transaction].IndividualPolicy ON [Transaction].IndividualPolicy.Id = [Transaction].Attachments.ReferenceId AND [Transaction].Attachments.AttachmentTypeId = 1 LEFT OUTER JOIN
                         [Transaction].PartnerPolicy ON [Transaction].PartnerPolicy.Id = [Transaction].Attachments.ReferenceId AND [Transaction].Attachments.AttachmentTypeId = 2 LEFT OUTER JOIN
                         [Transaction].GroupPolicy ON [Transaction].GroupPolicy.Id = [Transaction].Attachments.ReferenceId AND [Transaction].Attachments.AttachmentTypeId IN (3, 4) LEFT OUTER JOIN
                         [Transaction].PolicyPayments ON [Transaction].PolicyPayments.Id = [Transaction].Attachments.ReferenceId AND [Transaction].Attachments.AttachmentTypeId = 5 LEFT OUTER JOIN
                         [Transaction].IndividualPolicy AS IndividualPolicy_1 ON IndividualPolicy_1.Id = [Transaction].PolicyPayments.PolicyId AND [Transaction].PolicyPayments.PolicyTypeId = 1 LEFT OUTER JOIN
                         [Transaction].PartnerPolicy AS PartnerPolicy_1 ON PartnerPolicy_1.Id = [Transaction].PolicyPayments.PolicyId AND [Transaction].PolicyPayments.PolicyTypeId = 2 LEFT OUTER JOIN
                         [Transaction].GroupPolicy AS GroupPolicy_2 ON GroupPolicy_2.Id = [Transaction].PolicyPayments.PolicyId AND [Transaction].PolicyPayments.PolicyTypeId = 3
WHERE        ([Transaction].Attachments.IsDeleted = 0)
GO
