-- Create date: 06/02/2025 12:00:00 AM
-- Description:	Fetch Product Categories
-- =============================================

CREATE PROCEDURE [Reference].[GetProductCategory]
	@Id BIGINT = NULL,
	@IsActiveOnly bit = NULL
AS
BEGIN
	SET NOCOUNT ON;

	BEGIN TRY
		SELECT
			[PC].[Id],
			[PC].[Name],
			[PC].[Description],
			[PC].[Code],
			[PC].[CreatedBy],
			[PC].[CreatedDateTime],
			[PC].[ModifiedBy],
			[PC].[ModifiedDateTime],
			[PC].[IsActive]
		FROM
			[Reference].[ProductCategory] AS [PC]
		WHERE
			(@Id IS NULL OR [PC].[Id] = @Id)
			AND (@IsActiveOnly IS NULL OR [PC].[IsActive] = @IsActiveOnly)
			AND [PC].[IsDeleted] = 0
		ORDER BY
			[PC].[Id] ASC;
	END TRY
	BEGIN CATCH
		THROW;
	END CATCH
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

