-- =============================================
-- Author:		Dennis Jayvee Patricio (ddpatricio)
-- Create date: 06/02/2025 12:00:00 AM
-- Description:	Fetch Total Bookin Per Status (6M)
-- =============================================

CREATE PROCEDURE [dbo].[GetTotalBookingPerStatus6M]
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        DECLARE @EndDate DATE = CONVERT(DATE, GETUTCDATE());
        DECLARE @StartDate DATE = DATEADD(month, -6, @EndDate);

        DECLARE @GetDailyTotals BIT = 1;

        DECLARE @ColumnList NVARCHAR(MAX);
        DECLARE @PivotQuery NVARCHAR(MAX);
        DECLARE @TotalColumns NVARCHAR(MAX);
        DECLARE @AllStatusColumnsWithIsnull NVARCHAR(MAX);
        DECLARE @SummedStatusColumns NVARCHAR(MAX);

        SELECT @ColumnList = STUFF((
            SELECT ', [' + REPLACE(Name, '-', '') + ']'
            FROM [static].[PolicyBookingStatus]
            ORDER BY Id
            FOR XML PATH(''), TYPE
        ).value('.', 'NVARCHAR(MAX)'), 1, 2, '');

        -- Modify @AllStatusColumnsWithIsnull to include casting to INT
        SELECT @AllStatusColumnsWithIsnull = STUFF((
            SELECT ', CAST(ISNULL([' + REPLACE(Name, '-', '') + '], 0) AS INT) AS [' + REPLACE(Name, '-', '') + ']'
            FROM [static].[PolicyBookingStatus]
            ORDER BY Id
            FOR XML PATH(''), TYPE
        ).value('.', 'NVARCHAR(MAX)'), 1, 2, '');

        -- Dynamically create the SUM for each status column, with casting to INT
        SELECT @SummedStatusColumns = STUFF((
            SELECT ', CAST(SUM(ISNULL([' + REPLACE(Name, '-', '') + '], 0)) AS INT) AS [' + REPLACE(Name, '-', '') + ']'
            FROM [static].[PolicyBookingStatus]
            ORDER BY Id
            FOR XML PATH(''), TYPE
        ).value('.', 'NVARCHAR(MAX)'), 1, 2, '');

        SELECT @TotalColumns = STUFF((
            SELECT ' + ISNULL([' + REPLACE(Name, '-', '') + '], 0)'
            FROM [static].[PolicyBookingStatus]
            ORDER BY Id
            FOR XML PATH(''), TYPE
        ).value('.', 'NVARCHAR(MAX)'), 1, 3, '');

        SET @PivotQuery = '
        WITH DateSeries AS (
            -- Generate all dates between StartDate and EndDate
            SELECT DATEADD(day, number, @StartDate) AS ActivityDate
            FROM master.dbo.spt_values
            WHERE type = ''P'' AND number BETWEEN 0 AND DATEDIFF(day, @StartDate, @EndDate)
        ),
        DailyPolicyBookings AS (
            SELECT
                CONVERT(DATE, GP.CreatedDateTime) AS ActivityDate,
                GP.PolicyBookingStatusId
            FROM [Transaction].[GroupPolicy] AS GP
            WHERE CONVERT(DATE, GP.CreatedDateTime) >= @StartDate AND CONVERT(DATE, GP.CreatedDateTime) <= @EndDate AND GP.IsDeleted = 0

            UNION ALL

            SELECT
                CONVERT(DATE, IP.CreatedDateTime) AS ActivityDate,
                IP.PolicyBookingStatusId
            FROM [Transaction].[IndividualPolicy] AS IP
            WHERE CONVERT(DATE, IP.CreatedDateTime) >= @StartDate AND CONVERT(DATE, IP.CreatedDateTime) <= @EndDate AND IP.IsDeleted = 0

            UNION ALL

            SELECT
                CONVERT(DATE, PP.CreatedDateTime) AS ActivityDate,
                PP.PolicyBookingStatusId
            FROM [Transaction].[PartnerPolicy] AS PP
            WHERE CONVERT(DATE, PP.CreatedDateTime) >= @StartDate AND CONVERT(DATE, PP.CreatedDateTime) <= @EndDate AND PP.IsDeleted = 0
        ),
        DailyStatusRawCounts AS (
            SELECT
                dpb.ActivityDate,
                REPLACE(pbs.Name, ''-'', '''') AS StatusName,
                COUNT(*) AS StatusCount
            FROM DailyPolicyBookings AS dpb
            JOIN [static].[PolicyBookingStatus] AS pbs
                ON dpb.PolicyBookingStatusId = pbs.Id
            GROUP BY dpb.ActivityDate, REPLACE(pbs.Name, ''-'', '''')
        ),
        PivotedDailyData AS (
            SELECT
                ActivityDate,
                ' + @ColumnList + '
            FROM DailyStatusRawCounts
            PIVOT (
                SUM(StatusCount)
                FOR StatusName IN (' + @ColumnList + ')
            ) AS PivotTable
        )
        ';

        IF @GetDailyTotals = 1
        BEGIN
            SET @PivotQuery = @PivotQuery + '
            , NumberedRows AS (
                SELECT
                    CAST(ds.ActivityDate AS DATE) AS ActivityDate, -- Cast to DATE
                    ' + @AllStatusColumnsWithIsnull + ', -- All status columns with 0s for NULLs, cast to INT
                    CAST(ISNULL((' + @TotalColumns + '), 0) AS INT) AS TotalCount, -- Ensures DailyTotal is 0 if no activity, cast to INT
                    ROW_NUMBER() OVER (ORDER BY ds.ActivityDate) AS rn
                FROM DateSeries AS ds
                LEFT JOIN PivotedDailyData AS pdd
                    ON ds.ActivityDate = pdd.ActivityDate
            )
            SELECT
                CAST(MAX(ActivityDate) AS DATE) AS ActivityDate, -- Cast to DATE, assuming MAX(ActivityDate) is desired for the group
                ' + @SummedStatusColumns + ',
                CAST(SUM(TotalCount) AS INT) AS TotalCount -- Cast to INT
            FROM NumberedRows
            GROUP BY (rn - 1) / 2
            ORDER BY MIN(ActivityDate);';
        END
        ELSE
        BEGIN
            SET @PivotQuery = @PivotQuery + '
            SELECT
                CAST(''Overall Total'' AS NVARCHAR(15)) AS ActivityDate, -- Keep as NVARCHAR for overall total string
                ' + @AllStatusColumnsWithIsnull + ', -- All status columns with 0s for NULLs, cast to INT
                CAST(ISNULL((' + @TotalColumns + '), 0) AS INT) AS TotalCount -- Ensures OverallTotal is 0 if no activity, cast to INT
            FROM PivotedDailyData
            GROUP BY ()
            ';
        END

        EXEC sp_executesql @PivotQuery,
                           N'@StartDate DATE, @EndDate DATE',
                           @StartDate = @StartDate,
                           @EndDate = @EndDate;
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH
END;
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

