-- =============================================
-- Author:		Dennis Jayvee Patricio (ddpatricio)
-- Create date: 06/02/2025 12:00:00 AM
-- Description:	Fetch Total Bookin Per Status
-- =============================================

CREATE PROCEDURE [dbo].[GetTotalBookingPerStatus]
    @TimePeriodOption INT = 4
	--5 Years 	- 1
	--1 Year 	- 2
	--6 Months	- 3
	--30 Days	- 4
AS
BEGIN
    SET NOCOUNT ON;

    IF @TimePeriodOption IS NULL OR (@TimePeriodOption < 1 OR @TimePeriodOption > 4)
    BEGIN
        SET @TimePeriodOption = 4
    END

    BEGIN TRY
        IF @TimePeriodOption = 1
        BEGIN
            EXEC [dbo].[GetTotalBookingPerStatus5Y];
        END
        ELSE IF @TimePeriodOption = 2
        BEGIN
            EXEC [dbo].[GetTotalBookingPerStatus1Y];
        END
        ELSE IF @TimePeriodOption = 3
        BEGIN
            EXEC [dbo].[GetTotalBookingPerStatus6M];
        END
        ELSE IF @TimePeriodOption = 4
        BEGIN
            EXEC [dbo].[GetTotalBookingPerStatus30D];
        END
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH
END;
GO
