-- Author:      Dennis Jayvee Patricio (ddpatricio)
-- Create date: 06/02/2025 12:00:00 AM
-- Description: Fetch Attachments
-- =============================================

CREATE PROCEDURE [Transaction].[GetAttachments]
    @Id BIGINT = NULL,
    @ReferenceId BIGINT = NULL,
    @AttachmentTypeId BIGINT = NULL,
    @PageNumber int = 1, -- 0 For Last Page
    @PageSize int = 10 -- 0 To Fetch All
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        DECLARE @TotalCount bigint;
        DECLARE @TotalPages int;

        SELECT @TotalCount = COUNT(1)
        FROM [Transaction].[Attachments] AS [A]
        WHERE
            (@Id IS NULL OR [A].[Id] = @Id)
            AND (@ReferenceId IS NULL OR [A].[ReferenceId] = @ReferenceId)
            AND (@AttachmentTypeId IS NULL OR [A].[AttachmentTypeId] = @AttachmentTypeId)
            AND [A].[IsDeleted] = 0;

        IF @PageSize = 0
        BEGIN
            SET @PageNumber = 1;
            SET @PageSize = @TotalCount;
            IF @PageSize = 0 SET @PageSize = 1;
        END
        ELSE IF @PageNumber = 0
        BEGIN
            SET @TotalPages = CEILING(CAST(@TotalCount AS decimal) / @PageSize);
            SET @PageNumber = IIF(@TotalPages = 0, 1, @TotalPages);
        END
        ELSE IF @PageNumber < 1
        BEGIN
            SET @PageNumber = 1;
        END

        SELECT
            [A].[Id],
            [A].[ReferenceId],
            [A].[AttachmentTypeId],
            [A].[ContentType],
            [A].[FileName],
            [A].[Attachment],
            [A].[CreatedBy],
            [A].[CreatedDateTime],
            [A].[ModifiedBy],
            [A].[ModifiedDateTime]
        FROM
            [Transaction].[Attachments] AS [A]
        WHERE
            (@Id IS NULL OR [A].[Id] = @Id)
            AND (@ReferenceId IS NULL OR [A].[ReferenceId] = @ReferenceId)
            AND (@AttachmentTypeId IS NULL OR [A].[AttachmentTypeId] = @AttachmentTypeId)
            AND [A].[IsDeleted] = 0
        ORDER BY
            [A].[Id] ASC
        OFFSET (@PageNumber - 1) * @PageSize ROWS
        FETCH NEXT @PageSize ROWS ONLY;

		SELECT @TotalCount AS TotalRecords
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

