-- =============================================
-- Author:      Dennis Jayvee Patricio (ddpatricio)
-- Create date: 06/02/2025 12:00:00 AM
-- Description: Fetch Policy Beneficiaries
-- =============================================

CREATE PROCEDURE [Transaction].[GetPolicyBeneficiary]
    @Id BIGINT = NULL,
    @PolicyId BIGINT = NULL,
    @PolicyTypeId BIGINT = NULL,
    @PageNumber int = 1, -- 0 For Last Page
    @PageSize int = 10 -- 0 To Fetch All
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        DECLARE @TotalCount bigint;
        DECLARE @TotalPages int;

        SELECT @TotalCount = COUNT(1)
        FROM [Transaction].[PolicyBeneficiary] AS [PB]
        WHERE
            (@Id IS NULL OR [PB].[Id] = @Id)
            AND (@PolicyId IS NULL OR [PB].[PolicyId] = @PolicyId)
            AND (@PolicyTypeId IS NULL OR [PB].[PolicyTypeId] = @PolicyTypeId)
            AND [PB].[IsDeleted] = 0;

        IF @PageSize = 0
        BEGIN
            SET @PageNumber = 1;
            SET @PageSize = @TotalCount;
            IF @PageSize = 0 SET @PageSize = 1;
        END
        ELSE IF @PageNumber = 0
        BEGIN
            SET @TotalPages = CEILING(CAST(@TotalCount AS decimal) / @PageSize);
            SET @PageNumber = IIF(@TotalPages = 0, 1, @TotalPages);
        END
        ELSE IF @PageNumber < 1
        BEGIN
            SET @PageNumber = 1;
        END

        SELECT
            [PB].[Id],
            [PB].[PolicyId],
            [PB].[PolicyTypeId],
            [PB].[FirstName],
            [PB].[MiddleName],
            [PB].[LastName],
            [PB].[Suffix],
            [PB].[FullName],
            [PB].[EmailAddress],
            [PB].[ContactNumber],
            [PB].[DateOfBirth],
            [PB].[Relationship],
            [PB].[CreatedBy],
            [PB].[CreatedDateTime],
            [PB].[ModifiedBy],
            [PB].[ModifiedDateTime]
        FROM
            [Transaction].[PolicyBeneficiary] AS [PB]
        WHERE
            (@Id IS NULL OR [PB].[Id] = @Id)
            AND (@PolicyId IS NULL OR [PB].[PolicyId] = @PolicyId)
            AND (@PolicyTypeId IS NULL OR [PB].[PolicyTypeId] = @PolicyTypeId)
            AND [PB].[IsDeleted] = 0
        ORDER BY
            [PB].[Id] ASC
        OFFSET (@PageNumber - 1) * @PageSize ROWS
        FETCH NEXT @PageSize ROWS ONLY;

		SELECT @TotalCount AS TotalRecords
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

