			[PM].[Suffix],
			[PM].[FullName],
			[PM].[EmailAddress],
			[PM].[ContactNumber],
			[PM].[DateOfBirth],
			[PM].[Address1],
			[PM].[Address2],
			[PM].[AddressTownId],
			[PM].[Address],
			[PM].[CreatedBy],
			[PM].[CreatedDateTime],
			[PM].[ModifiedBy],
			[PM].[ModifiedDateTime],
			[PM].[IsActive]
		FROM
			[Reference].[PromoManagers] AS [PM]
		WHERE
			(@Id IS NULL OR [PM].[Id] = @Id)
			AND (@IsActiveOnly IS NULL OR [PM].[IsActive] = @IsActiveOnly)
			AND (@DJDPatricioOrAgentId IS NULL OR [PM].[DJDPatricioOrAgentId] = @DJDPatricioOrAgentId)
			AND (@AgentsId IS NULL OR [PM].[AgentsId] = @AgentsId)
			AND [PM].[IsDeleted] = 0
		ORDER BY
			[PM].[Id] ASC;
	END TRY
	BEGIN CATCH
		THROW;
	END CATCH
END
