-- =============================================
-- Author: Dennis Jayvee Patricio (ddpatricio)
-- Create date: 06/02/2025 12:00:00 AM
-- Description: Fetch Group Policy
-- =============================================

CREATE PROCEDURE [Transaction].[GetGroupPolicy]
    @Id bigint = NULL,
    @ReferenceNumber nvarchar(15) = NULL,
    @CocNumber nvarchar(15) = NULL,
    @PartnersId bigint = NULL,
    @IssueStatus bit = NULL,
    @PolicyBookingStatusId nvarchar(MAX) = NULL,	-- Id's separated by comma
    @CocStatusId nvarchar(MAX) = NULL,				-- Id's separated by comma
    @PaymentStatusId nvarchar(MAX) = NULL,			-- Id's separated by comma
    @ClaimsStatusId nvarchar(MAX) = NULL,			-- Id's separated by comma
    @PageNumber int = 1, -- 0 For Last Page
    @PageSize int = 10 -- 0 To Fetch All
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        DECLARE @TotalCount bigint;
        DECLARE @TotalPages int;

        SELECT @TotalCount = COUNT(1)
        FROM [Transaction].[GroupPolicy] AS [GP]
        LEFT JOIN [Transaction].[PolicyPremiums] AS [PP] ON [PP].[PolicyId] = [GP].[Id] AND [PP].[PolicyTypeId] = 3
        WHERE
            (@Id IS NULL OR [GP].[Id] = @Id)
            AND (@ReferenceNumber IS NULL OR [GP].[ReferenceNumber] = @ReferenceNumber)
            AND (@CocNumber IS NULL OR [GP].[CocNumber] = @CocNumber)
            AND (@PartnersId IS NULL OR [GP].[PartnersId] = @PartnersId)
            AND (@IssueStatus IS NULL OR [GP].[IssueStatus] = @IssueStatus)
            AND (@PolicyBookingStatusId IS NULL OR EXISTS (SELECT 1 FROM STRING_SPLIT(@PolicyBookingStatusId, ',') WHERE TRY_CAST(value AS BIGINT) = [GP].[PolicyBookingStatusId]))
            AND (@CocStatusId IS NULL OR EXISTS (SELECT 1 FROM STRING_SPLIT(@CocStatusId, ',') WHERE TRY_CAST(value AS BIGINT) = [GP].[CocStatusId]))
            AND (@PaymentStatusId IS NULL OR EXISTS (SELECT 1 FROM STRING_SPLIT(@PaymentStatusId, ',') WHERE TRY_CAST(value AS BIGINT) = [GP].[PaymentStatusId]))
            AND (@ClaimsStatusId IS NULL OR EXISTS (SELECT 1 FROM STRING_SPLIT(@ClaimsStatusId, ',') WHERE TRY_CAST(value AS BIGINT) = [GP].[ClaimsStatusId]))
            AND [GP].[IsDeleted] = 0;

        IF @PageSize = 0
        BEGIN
            SET @PageNumber = 1;
            SET @PageSize = @TotalCount;
            IF @PageSize = 0 SET @PageSize = 1;
        END
        ELSE IF @PageNumber = 0
        BEGIN
            SET @TotalPages = CEILING(CAST(@TotalCount AS decimal) / @PageSize);
            SET @PageNumber = IIF(@TotalPages = 0, 1, @TotalPages);
        END
        ELSE IF @PageNumber < 1
        BEGIN
            SET @PageNumber = 1;
        END

        SELECT
            [GP].[Id],
            [GP].[ReferenceNumber],
            [GP].[CocNumber],
            [GP].[PartnersId],
            [GP].[PlatformsId],
            [GP].[IssueStatus],
            [GP].[PolicyBookingStatusId],
            [GP].[CocStatusId],
            [GP].[PaymentStatusId],
            [GP].[ClaimsStatusId],
            [GP].[AgentsId],
            [GP].[SubAgentsId],
            [GP].[ApproversId],
            [GP].[PromoManagersId],
            [GP].[SalesManagersId],
            [GP].[PromoOfficersId],
            [GP].[ProductsId],
            [GP].[ProvidersId],
            [GP].[DistributionChannelId],
            [GP].[PaymentOptionId],
            [GP].[AccountTypeId],
            [GP].[BranchCode],
            [GP].[BranchName],
            [GP].[ProviderPolicyNo],
            [GP].[EndorsementNo],
            [GP].[TerminationDate],
            [GP].[EffectiveDate],
            [GP].[IssueDate],
            [GP].[Remarks],
            [GP].[TotalPremium],
            [GP].[TotalCoverage],
            [GP].[TotalPaid],
            [GP].[CreatedBy],
            [GP].[CreatedDateTime],
            [GP].[ModifiedBy],
            [GP].[ModifiedDateTime],

            --Premiums
            [PP].[BasicPremium],
            [PP].[BasicPremiumCommission],
            [PP].[DJDPatricioMarkup],
            [PP].[PartnerMarkup],
            [PP].[Discount],
            [PP].[Taxes],
            [PP].[DST],
            [PP].[VAT],
            [PP].[LGT],
            [PP].[PT],
            [PP].[FST],
            [PP].[NotarialFee],
            [PP].[Others],
            [PP].[Remarks] AS [PremiumsRemarks]
        FROM
            [Transaction].[GroupPolicy] AS [GP]
            LEFT JOIN [Transaction].[PolicyPremiums] AS [PP] ON [PP].[PolicyId] = [GP].[Id] AND [PP].[PolicyTypeId] = 3
        WHERE
            (@Id IS NULL OR [GP].[Id] = @Id)
            AND (@ReferenceNumber IS NULL OR [GP].[ReferenceNumber] = @ReferenceNumber)
            AND (@CocNumber IS NULL OR [GP].[CocNumber] = @CocNumber)
            AND (@PartnersId IS NULL OR [GP].[PartnersId] = @PartnersId)
            AND (@IssueStatus IS NULL OR [GP].[IssueStatus] = @IssueStatus)
            AND (@PolicyBookingStatusId IS NULL OR EXISTS (SELECT 1 FROM STRING_SPLIT(@PolicyBookingStatusId, ',') WHERE TRY_CAST(value AS BIGINT) = [GP].[PolicyBookingStatusId]))
            AND (@CocStatusId IS NULL OR EXISTS (SELECT 1 FROM STRING_SPLIT(@CocStatusId, ',') WHERE TRY_CAST(value AS BIGINT) = [GP].[CocStatusId]))
            AND (@PaymentStatusId IS NULL OR EXISTS (SELECT 1 FROM STRING_SPLIT(@PaymentStatusId, ',') WHERE TRY_CAST(value AS BIGINT) = [GP].[PaymentStatusId]))
            AND (@ClaimsStatusId IS NULL OR EXISTS (SELECT 1 FROM STRING_SPLIT(@ClaimsStatusId, ',') WHERE TRY_CAST(value AS BIGINT) = [GP].[ClaimsStatusId]))
            AND [GP].[IsDeleted] = 0
        ORDER BY
            [GP].[Id] ASC
        OFFSET (@PageNumber - 1) * @PageSize ROWS
        FETCH NEXT @PageSize ROWS ONLY;

        SELECT @TotalCount AS TotalRecords;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- Author:		Dennis Jayvee Patricio (ddpatricio)
-- Create date: 06/02/2025 12:00:00 AM
-- Description:	Update Policy Payments
-- =============================================

CREATE PROCEDURE [Transaction].[PutPolicyPayments]
	@Id bigint,
	@Amount decimal(18,2),
    @TransactionDateTime datetime2(7),
    @TransactionCheckNo nvarchar(50),
    @TransactionOrigin nvarchar(50),
    @NotificationDateTime datetime2(7),
    @PaymentMethod bigint,
    @Notes nvarchar(500) = NULL,
	@IsDeleted bit = 0,
	@UserId bigint
AS
BEGIN
	SET NOCOUNT ON;

	BEGIN TRY
		BEGIN TRANSACTION;

		IF NOT EXISTS (SELECT 1 FROM [Transaction].[PolicyPayments] WHERE [Id] = @Id AND IsDeleted = 0)
		BEGIN
			RAISERROR ('CustomSQLException: Payment not found.', 16, 1);
			RETURN;
		END

		DECLARE @CurrentDateTime datetime2(7) = GETUTCDATE();

		IF @IsDeleted = 1
		BEGIN
			UPDATE [Transaction].[PolicyPayments]
			SET 
				[DeletedBy] = @UserId,
				[DeletedDateTime] = @CurrentDateTime,
				[IsDeleted] = @IsDeleted
			WHERE 
				[Id] = @Id;

			--Update Links
			UPDATE [Transaction].[Attachments]
			SET 
				[DeletedBy] = @UserId,
				[DeletedDateTime] = @CurrentDateTime,
				[IsDeleted] = @IsDeleted
			WHERE 
				[ReferenceId] = @Id AND AttachmentTypeId = 5 AND [IsDeleted] = 0;
		END
		ELSE
		BEGIN
			UPDATE [Transaction].[PolicyPayments]
			SET 
				[Amount] = @Amount,
				[TransactionDateTime] = @TransactionDateTime,
				[TransactionCheckNo] = @TransactionCheckNo,
				[TransactionOrigin] = @TransactionOrigin,
				[NotificationDateTime] = @NotificationDateTime,
				[PaymentMethod] = @PaymentMethod,
				[Notes] = @Notes,
				[ModifiedBy] = @UserId,
				[ModifiedDateTime] = @CurrentDateTime
			WHERE
				[Id] = @Id;
		END

		--Update Reference
		DECLARE @PolicyTypeId BIGINT = NULL;
		DECLARE @PolicyId BIGINT = NULL;
		SELECT @PolicyTypeId = PolicyTypeId, @PolicyId = PolicyId FROM [Transaction].[PolicyPayments] WHERE [Id] = @Id;

		--Check Totals
		DECLARE @TotalPaid decimal(18,2) = 0;
		SELECT @TotalPaid = ISNULL(SUM([Amount]), 0) FROM [Transaction].[PolicyPayments] WHERE [PolicyId] = @PolicyId AND [PolicyTypeId] = @PolicyTypeId AND IsDeleted = 0;

		DECLARE @TotalPremiumsBenefit decimal(18,2) = 0;
		DECLARE @TotalCoverage decimal(18,2) = 0;
		SELECT @TotalPremiumsBenefit = ISNULL(SUM([PremiumAmount]), 0), @TotalCoverage = ISNULL(SUM([CoverageAmount]), 0)
		FROM [Transaction].[PolicyBenefits] WHERE [PolicyId] = @PolicyId AND [PolicyTypeId] = @PolicyTypeId AND IsDeleted = 0;

		DECLARE @TotalPremiums decimal(18,2) = 0;
		SELECT @TotalPremiums = SUM([BasicPremium] + [DJDPatricioMarkup] + [PartnerMarkup] + [Taxes] + [DST] + [VAT] + [LGT] + [PT] + [FST] + [NotarialFee] + [Others] - [Discount])
		FROM [Transaction].[PolicyPremiums] WHERE [PolicyId] = @PolicyId AND [PolicyTypeId] = @PolicyTypeId AND IsDeleted = 0;
		SET @TotalPremiums = @TotalPremiums + @TotalPremiumsBenefit

		DECLARE @PaymentStatusId bigint;
		IF @TotalPremiums = @TotalPaid
			SET @PaymentStatusId = 1;
		IF @TotalPaid = 0
		BEGIN
			SET @PaymentStatusId = 2;
		END
		ELSE
		BEGIN
			IF @TotalPremiums > @TotalPaid
				SET @PaymentStatusId = 3;
			IF @TotalPremiums < @TotalPaid
				SET @PaymentStatusId = 5;
		END

		--Individual
		IF @PolicyTypeId = 1
			UPDATE [Transaction].[IndividualPolicy] 
			SET [PaymentStatusId] = @PaymentStatusId,
				[TotalPremium] = @TotalPremiums, 
				[TotalCoverage] = @TotalCoverage, 
				[TotalPaid] = @TotalPaid, 
				[ModifiedBy] = @UserId, 
				[ModifiedDateTime] = @CurrentDateTime 
			WHERE [Id] = @PolicyId;

		--Partner
		ELSE IF @PolicyTypeId = 2
			UPDATE [Transaction].[PartnerPolicy] 
			SET [PaymentStatusId] = @PaymentStatusId,
				[TotalPremium] = @TotalPremiums, 
				[TotalCoverage] = @TotalCoverage, 
				[TotalPaid] = @TotalPaid, 
				[ModifiedBy] = @UserId, 
				[ModifiedDateTime] = @CurrentDateTime 
			WHERE [Id] = @PolicyId;
			
		--Group
		ELSE
			UPDATE [Transaction].[GroupPolicy] 
			SET [PaymentStatusId] = @PaymentStatusId,
				[TotalPremium] = @TotalPremiums, 
				[TotalCoverage] = @TotalCoverage, 
				[TotalPaid] = @TotalPaid, 
				[ModifiedBy] = @UserId, 
				[ModifiedDateTime] = @CurrentDateTime 
			WHERE [Id] = @PolicyId;

		COMMIT;
	END TRY
	BEGIN CATCH
		IF @@TRANCOUNT > 0
			ROLLBACK;
		THROW;
	END CATCH
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- Author:		Dennis Jayvee Patricio (ddpatricio)
-- Create date: 06/02/2025 12:00:00 AM
-- Description:	Update Policy Beneficiary
-- =============================================

CREATE PROCEDURE [Transaction].[PutPolicyBeneficiary]
	@Id bigint,
    @FirstName nvarchar(60),
    @MiddleName nvarchar(60) = NULL,
    @LastName nvarchar(60),
    @Suffix nvarchar(10) = NULL,
    @EmailAddress nvarchar(100),
    @ContactNumber nvarchar(20),
    @DateOfBirth date,
    @Relationship bigint,
	@IsDeleted bit = 0,
	@UserId bigint
AS
BEGIN
	SET NOCOUNT ON;

	BEGIN TRY
		BEGIN TRANSACTION;

		DECLARE @FullName nvarchar(200);
		DECLARE @MiddleInitial nvarchar(5);

		IF @MiddleName IS NOT NULL AND LTRIM(RTRIM(@MiddleName)) <> ''
		BEGIN
			SET @MiddleInitial = SUBSTRING(LTRIM(RTRIM(@MiddleName)), 1, 1) + '.';
		END
		ELSE
		BEGIN
			SET @MiddleInitial = '';
		END

		SET @FullName = LTRIM(RTRIM(
						COALESCE(@FirstName, '') +
						CASE WHEN @MiddleInitial <> '' THEN ' ' + @MiddleInitial ELSE '' END +
						CASE WHEN @LastName IS NOT NULL AND @LastName <> '' THEN ' ' + @LastName ELSE '' END +
						CASE WHEN @Suffix IS NOT NULL AND @Suffix <> '' THEN ' ' + @Suffix ELSE '' END
					));

		IF NOT EXISTS (SELECT 1 FROM [Transaction].[PolicyBeneficiary] WHERE [Id] = @Id AND IsDeleted = 0)
		BEGIN
			RAISERROR ('CustomSQLException: Beneficiary not found.', 16, 1);
			RETURN;
		END

		IF NOT EXISTS (SELECT 1 FROM [Transaction].[PolicyBeneficiary] WHERE FullName = @FullName AND Id != @Id AND IsDeleted = 0)
		BEGIN
			RAISERROR ('CustomSQLException: Beneficiary already exists.', 16, 1);
			RETURN;
		END

		DECLARE @CurrentDateTime datetime2(7) = GETUTCDATE();

		IF @IsDeleted = 1
		BEGIN
			UPDATE [Transaction].[PolicyBeneficiary]
			SET 
				[DeletedBy] = @UserId,
				[DeletedDateTime] = @CurrentDateTime,
				[IsDeleted] = @IsDeleted
			WHERE 
				[Id] = @Id;
		END
		ELSE
		BEGIN
			UPDATE [Transaction].[PolicyBeneficiary]
			SET 
				[FirstName] = @FirstName,
				[MiddleName] = @MiddleName,
				[LastName] = @LastName,
				[Suffix] = @Suffix,
				[FullName] = @FullName,
				[EmailAddress] = @EmailAddress,
				[ContactNumber] = @ContactNumber,
				[DateOfBirth] = @DateOfBirth,
				[Relationship] = @Relationship,
				[ModifiedBy] = @UserId,
				[ModifiedDateTime] = @CurrentDateTime
			WHERE 
				[Id] = @Id;
		END

		--Update Reference
		DECLARE @PolicyTypeId BIGINT = NULL;
		DECLARE @PolicyId BIGINT = NULL;
		SELECT @PolicyTypeId = PolicyTypeId, @PolicyId = PolicyId FROM [Transaction].[PolicyBeneficiary] WHERE [Id] = @Id;
		--Individual
		IF @PolicyTypeId = 1
			UPDATE [Transaction].[IndividualPolicy] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @PolicyId;

		--Partner
		ELSE IF @PolicyTypeId = 2
			UPDATE [Transaction].[PartnerPolicy] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @PolicyId;

		--Group
		ELSE
			UPDATE [Transaction].[GroupPolicy] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @PolicyId;

		COMMIT;
	END TRY
	BEGIN CATCH
		IF @@TRANCOUNT > 0
			ROLLBACK;
		THROW;
	END CATCH
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

