-- Description:	Update Individual Policy
-- =============================================

CREATE PROCEDURE [Transaction].[PutIndividualPolicy]
	@Id bigint,
    @IssueStatus bit,
    @PolicyBookingStatusId bigint,
    @CocStatusId bigint,
    @ClaimsStatusId bigint,
    @AgentsId bigint,
    @SubAgentsId bigint = NULL,
    @ApproversId bigint,
	@PromoManagersId bigint = NULL,
	@SalesManagersId bigint = NULL,
	@PromoOfficersId bigint = NULL,
	@Remarks nvarchar(500) = NULL,
	@IsDeleted bit = 0,

	--Premiums
	@BasicPremium decimal(18,2),
    @BasicPremiumCommission decimal(18,2),
    @DJDPatricioMarkup decimal(18,2),
    @PartnerMarkup decimal(18,2),
    @Discount decimal(18,2),
    @Taxes decimal(18,2),
    @DST decimal(18,2),
    @VAT decimal(18,2),
    @LGT decimal(18,2),
    @PT decimal(18,2),
    @FST decimal(18,2),
    @NotarialFee decimal(18,2),
    @Others decimal(18,2),
	@PremiumsRemarks nvarchar(500) = NULL,

	@UserId bigint
AS
BEGIN
	SET NOCOUNT ON;

	BEGIN TRY
		BEGIN TRANSACTION;

		IF NOT EXISTS (SELECT 1 FROM [Transaction].[IndividualPolicy] WHERE [Id] = @Id AND IsDeleted = 0)
		BEGIN
			RAISERROR ('CustomSQLException: Policy not found.', 16, 1);
			RETURN;
		END

		DECLARE @CurrentDateTime datetime2(7) = GETUTCDATE();

		IF @IsDeleted = 1
		BEGIN
			UPDATE [Transaction].[IndividualPolicy]
			SET 
				[DeletedBy] = @UserId,
				[DeletedDateTime] = @CurrentDateTime,
				[IsDeleted] = @IsDeleted
			WHERE 
				[Id] = @Id;

			--Update Links
			UPDATE [Transaction].[PolicyBeneficiary]
			SET 
				[DeletedBy] = @UserId,
				[DeletedDateTime] = @CurrentDateTime,
				[IsDeleted] = @IsDeleted
			WHERE 
				[PolicyId] = @Id AND [PolicyTypeId] = 1 AND [IsDeleted] = 0;

			UPDATE [Transaction].[PolicyBenefits]
			SET 
				[DeletedBy] = @UserId,
				[DeletedDateTime] = @CurrentDateTime,
				[IsDeleted] = @IsDeleted
			WHERE 
				[PolicyId] = @Id AND [PolicyTypeId] = 1 AND [IsDeleted] = 0;

			UPDATE [Transaction].[PolicyDeductibles]
			SET 
				[DeletedBy] = @UserId,
				[DeletedDateTime] = @CurrentDateTime,
				[IsDeleted] = @IsDeleted
			WHERE 
				[PolicyId] = @Id AND [PolicyTypeId] = 1 AND [IsDeleted] = 0;

			UPDATE [Transaction].[PolicyPayments]
			SET 
				[DeletedBy] = @UserId,
				[DeletedDateTime] = @CurrentDateTime,
				[IsDeleted] = @IsDeleted
			WHERE 
				[PolicyId] = @Id AND [PolicyTypeId] = 1 AND [IsDeleted] = 0;

			UPDATE [Transaction].[Attachments]
			SET 
				[DeletedBy] = @UserId,
				[DeletedDateTime] = @CurrentDateTime,
				[IsDeleted] = @IsDeleted
			WHERE 
				ReferenceId IN (SELECT Id FROM [Transaction].[PolicyPayments] WHERE PolicyId = @Id AND [PolicyTypeId] = 1 AND [IsDeleted] = 0)
				AND AttachmentTypeId = 5
				AND [IsDeleted] = 0;

			UPDATE [Transaction].[PolicyPremiums]
			SET 
				[DeletedBy] = @UserId,
				[DeletedDateTime] = @CurrentDateTime,
				[IsDeleted] = @IsDeleted
			WHERE 
				[PolicyId] = @Id AND [PolicyTypeId] = 1 AND [IsDeleted] = 0;

			UPDATE [Transaction].[Attachments]
			SET 
				[DeletedBy] = @UserId,
				[DeletedDateTime] = @CurrentDateTime,
				[IsDeleted] = @IsDeleted
			WHERE 
				[ReferenceId] = @Id AND AttachmentTypeId = 1 AND [IsDeleted] = 0;
		END
		ELSE
		BEGIN
			UPDATE [Transaction].[IndividualPolicy]
			SET 
				[IssueStatus] = @IssueStatus,
				[PolicyBookingStatusId] = @PolicyBookingStatusId,
				[CocStatusId] = @CocStatusId,
				[ClaimsStatusId] = @ClaimsStatusId,
				[AgentsId] = @AgentsId,
				[SubAgentsId] = @SubAgentsId,
				[ApproversId] = @ApproversId,
				[PromoManagersId] = @PromoManagersId,
				[SalesManagersId] = @SalesManagersId,
				[PromoOfficersId] = @PromoOfficersId,
				[Remarks] = @Remarks,
				[ModifiedBy] = @UserId,
				[ModifiedDateTime] = @CurrentDateTime
			WHERE 
				[Id] = @Id;

			UPDATE [Transaction].[PolicyPremiums]
			SET 
				[BasicPremium] = @BasicPremium,
				[BasicPremiumCommission] = @BasicPremiumCommission,
				[DJDPatricioMarkup] = @DJDPatricioMarkup,
				[PartnerMarkup] = @PartnerMarkup,
				[Discount] = @Discount,
				[Taxes] = @Taxes,
				[DST] = @DST,
				[VAT] = @VAT,
				[LGT] = @LGT,
				[PT] = @PT,
				[FST] = @FST,
				[NotarialFee] = @NotarialFee,
				[Others] = @Others,
				[Remarks] = @PremiumsRemarks,
				[ModifiedBy] = @UserId,
				[ModifiedDateTime] = @CurrentDateTime
			WHERE 
				[PolicyId] = @Id AND [PolicyTypeId] = 1;

			--Update Reference
			--Check Totals
			DECLARE @TotalPaid decimal(18,2) = 0;
			SELECT @TotalPaid = ISNULL(SUM([Amount]), 0) FROM [Transaction].[PolicyPayments] WHERE [PolicyId] = @Id AND [PolicyTypeId] = 1 AND IsDeleted = 0;

			DECLARE @TotalPremiumsBenefit decimal(18,2) = 0;
			DECLARE @TotalCoverage decimal(18,2) = 0;
			SELECT @TotalPremiumsBenefit = ISNULL(SUM([PremiumAmount]), 0), @TotalCoverage = ISNULL(SUM([CoverageAmount]), 0)
			FROM [Transaction].[PolicyBenefits] WHERE [PolicyId] = @Id AND [PolicyTypeId] = 1 AND IsDeleted = 0;

			DECLARE @TotalPremiums decimal(18,2) = 0;
			SELECT @TotalPremiums = SUM([BasicPremium] + [DJDPatricioMarkup] + [PartnerMarkup] + [Taxes] + [DST] + [VAT] + [LGT] + [PT] + [FST] + [NotarialFee] + [Others] - [Discount])
			FROM [Transaction].[PolicyPremiums] WHERE [PolicyId] = @Id AND [PolicyTypeId] = 1 AND IsDeleted = 0;
			SET @TotalPremiums = @TotalPremiums + @TotalPremiumsBenefit

			DECLARE @PaymentStatusId bigint;
			IF @TotalPremiums = @TotalPaid
				SET @PaymentStatusId = 1;
			IF @TotalPaid = 0
			BEGIN
				SET @PaymentStatusId = 2;
			END
			ELSE
			BEGIN
				IF @TotalPremiums > @TotalPaid
					SET @PaymentStatusId = 3;
				IF @TotalPremiums < @TotalPaid
					SET @PaymentStatusId = 5;
			END

			--Individual
			UPDATE [Transaction].[IndividualPolicy] 
			SET [PaymentStatusId] = @PaymentStatusId,
				[TotalPremium] = @TotalPremiums, 
				[TotalCoverage] = @TotalCoverage, 
				[TotalPaid] = @TotalPaid
			WHERE [Id] = @Id;
		END

		COMMIT;
	END TRY
	BEGIN CATCH
		IF @@TRANCOUNT > 0
			ROLLBACK;
		THROW;
	END CATCH
END
GO
