-- =============================================
-- Author:		Dennis Jayvee Patricio (ddpatricio)
-- Create date: 06/02/2025 12:00:00 AM
-- Description:	Update Attachments
-- =============================================

CREATE PROCEDURE [Transaction].[PutAttachments]
	@Id bigint,
	@ContentType nvarchar(200) = NULL,
    @FileName nvarchar(max),
    @Attachment varbinary(max),
	@IsDeleted bit = 0,
	@UserId bigint
AS
BEGIN
	SET NOCOUNT ON;

	BEGIN TRY
		BEGIN TRANSACTION;

		IF NOT EXISTS (SELECT 1 FROM [Transaction].[Attachments] WHERE [Id] = @Id AND IsDeleted = 0)
		BEGIN
			RAISERROR ('CustomSQLException: Attachment not found.', 16, 1);
			RETURN;
		END

		DECLARE @CurrentDateTime datetime2(7) = GETUTCDATE();

		IF @IsDeleted = 1
		BEGIN
			UPDATE [Transaction].[Attachments]
			SET 
				[DeletedBy] = @UserId,
				[DeletedDateTime] = @CurrentDateTime,
				[IsDeleted] = @IsDeleted
			WHERE 
				[Id] = @Id;
		END
		ELSE
		BEGIN
			UPDATE [Transaction].[Attachments]
			SET 
				[ContentType] = @ContentType,
				[FileName] = @FileName,
				[Attachment] = @Attachment,
				[ModifiedBy] = @UserId,
				[ModifiedDateTime] = @CurrentDateTime
			WHERE 
				[Id] = @Id;
		END
		
		--Update Reference
		DECLARE @AttachmentTypeId BIGINT = NULL;
		DECLARE @ReferenceId BIGINT = NULL;
		SELECT @AttachmentTypeId = AttachmentTypeId, @ReferenceId = ReferenceId FROM [Transaction].[Attachments] WHERE [Id] = @Id;
		IF @AttachmentTypeId IN (1, 2, 3, 4)
		BEGIN
			--Individual
			IF @AttachmentTypeId = 1
				UPDATE [Transaction].[IndividualPolicy] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @ReferenceId;

			--Partner
			ELSE IF @AttachmentTypeId = 2
				UPDATE [Transaction].[PartnerPolicy] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @ReferenceId;

			--Group Policy Copy or DeclarationFile
			ELSE
				UPDATE [Transaction].[GroupPolicy] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @ReferenceId;
		END
		ELSE
		BEGIN
			--Payments
			UPDATE [Transaction].[PolicyPayments] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @ReferenceId;

			DECLARE @PolicyTypeId BIGINT = NULL;
			DECLARE @PolicyId BIGINT = NULL;
			SELECT @PolicyTypeId = PolicyTypeId, @PolicyId = PolicyId FROM [Transaction].[PolicyPayments] WHERE [Id] = @ReferenceId;

			--Update Reference
			--Individual
			IF @PolicyTypeId = 1
				UPDATE [Transaction].[IndividualPolicy] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @PolicyId;

			--Partner
			ELSE IF @PolicyTypeId = 2
				UPDATE [Transaction].[PartnerPolicy] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @PolicyId;

			--Group
			ELSE
				UPDATE [Transaction].[GroupPolicy] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @PolicyId;
		END

		COMMIT;
	END TRY
	BEGIN CATCH
		IF @@TRANCOUNT > 0
			ROLLBACK;
		THROW;
	END CATCH
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- Author:		Dennis Jayvee Patricio (ddpatricio)
-- Create date: 06/02/2025 12:00:00 AM
-- Description:	Insert Policy Payments
-- =============================================

CREATE PROCEDURE [Transaction].[PostPolicyPayments]
	@PolicyId bigint,
	@PolicyTypeId bigint,
	@Amount decimal(18,2),
    @TransactionDateTime datetime2(7),
    @TransactionCheckNo nvarchar(50),
    @TransactionOrigin nvarchar(50),
    @NotificationDateTime datetime2(7),
    @PaymentMethod bigint,
    @Notes nvarchar(500) = NULL,
	@UserId bigint
AS
BEGIN
	SET NOCOUNT ON;

	BEGIN TRY
		BEGIN TRANSACTION;

		IF (
			(@PolicyTypeId = 1 AND NOT EXISTS (SELECT 1 FROM [Transaction].[IndividualPolicy] WHERE [Id] = @PolicyId AND IsDeleted = 0)) OR
			(@PolicyTypeId = 2 AND NOT EXISTS (SELECT 1 FROM [Transaction].[PartnerPolicy] WHERE [Id] = @PolicyId AND IsDeleted = 0)) OR
			(@PolicyTypeId = 3 AND NOT EXISTS (SELECT 1 FROM [Transaction].[GroupPolicy] WHERE [Id] = @PolicyId AND IsDeleted = 0))
		)
		BEGIN
			RAISERROR ('CustomSQLException: Policy not found.', 16, 1);
			RETURN;
		END

		DECLARE @CurrentDateTime datetime2(7) = GETUTCDATE();

		INSERT INTO [Transaction].[PolicyPayments]
			([PolicyId]
			,[PolicyTypeId]
			,[Amount]
			,[TransactionDateTime]
			,[TransactionCheckNo]
			,[TransactionOrigin]
			,[NotificationDateTime]
			,[PaymentMethod]
			,[Notes]
			,[CreatedBy]
			,[CreatedDateTime]
			,[ModifiedBy]
			,[ModifiedDateTime])
		VALUES
			(@PolicyId
			,@PolicyTypeId
			,@Amount
			,@TransactionDateTime
			,@TransactionCheckNo
			,@TransactionOrigin
			,@NotificationDateTime
			,@PaymentMethod
			,@Notes
			,@UserId
			,@CurrentDateTime
			,@UserId
			,@CurrentDateTime)
		DECLARE @PolicyPaymentsId BIGINT = SCOPE_IDENTITY();
		
		--Update Reference
		--Check Totals
		DECLARE @TotalPaid decimal(18,2) = 0;
		SELECT @TotalPaid = ISNULL(SUM([Amount]), 0) FROM [Transaction].[PolicyPayments] WHERE [PolicyId] = @PolicyId AND [PolicyTypeId] = @PolicyTypeId AND IsDeleted = 0;

		DECLARE @TotalPremiumsBenefit decimal(18,2) = 0;
		DECLARE @TotalCoverage decimal(18,2) = 0;
		SELECT @TotalPremiumsBenefit = ISNULL(SUM([PremiumAmount]), 0), @TotalCoverage = ISNULL(SUM([CoverageAmount]), 0)
		FROM [Transaction].[PolicyBenefits] WHERE [PolicyId] = @PolicyId AND [PolicyTypeId] = @PolicyTypeId AND IsDeleted = 0;

		DECLARE @TotalPremiums decimal(18,2) = 0;
		SELECT @TotalPremiums = SUM([BasicPremium] + [DJDPatricioMarkup] + [PartnerMarkup] + [Taxes] + [DST] + [VAT] + [LGT] + [PT] + [FST] + [NotarialFee] + [Others] - [Discount])
		FROM [Transaction].[PolicyPremiums] WHERE [PolicyId] = @PolicyId AND [PolicyTypeId] = @PolicyTypeId AND IsDeleted = 0;
		SET @TotalPremiums = @TotalPremiums + @TotalPremiumsBenefit

		DECLARE @PaymentStatusId bigint;
		IF @TotalPremiums = @TotalPaid
			SET @PaymentStatusId = 1;
		IF @TotalPaid = 0
		BEGIN
			SET @PaymentStatusId = 2;
		END
		ELSE
		BEGIN
			IF @TotalPremiums > @TotalPaid
				SET @PaymentStatusId = 3;
			IF @TotalPremiums < @TotalPaid
				SET @PaymentStatusId = 5;
		END

		--Individual
		IF @PolicyTypeId = 1
			UPDATE [Transaction].[IndividualPolicy] 
			SET [PaymentStatusId] = @PaymentStatusId,
				[TotalPremium] = @TotalPremiums, 
				[TotalCoverage] = @TotalCoverage, 
				[TotalPaid] = @TotalPaid, 
				[ModifiedBy] = @UserId, 
				[ModifiedDateTime] = @CurrentDateTime 
			WHERE [Id] = @PolicyId;

		--Partner
		ELSE IF @PolicyTypeId = 2
			UPDATE [Transaction].[PartnerPolicy] 
			SET [PaymentStatusId] = @PaymentStatusId,
				[TotalPremium] = @TotalPremiums, 
				[TotalCoverage] = @TotalCoverage, 
				[TotalPaid] = @TotalPaid, 
				[ModifiedBy] = @UserId, 
				[ModifiedDateTime] = @CurrentDateTime 
			WHERE [Id] = @PolicyId;
			
		--Group
		ELSE
			UPDATE [Transaction].[GroupPolicy] 
			SET [PaymentStatusId] = @PaymentStatusId,
				[TotalPremium] = @TotalPremiums, 
				[TotalCoverage] = @TotalCoverage, 
				[TotalPaid] = @TotalPaid, 
				[ModifiedBy] = @UserId, 
				[ModifiedDateTime] = @CurrentDateTime 
			WHERE [Id] = @PolicyId;
			
		SELECT CAST(@PolicyPaymentsId AS BIGINT) AS Id;

		COMMIT;
	END TRY
	BEGIN CATCH
		IF @@TRANCOUNT > 0
			ROLLBACK;
		THROW;
	END CATCH
END
GO
