-- =============================================
-- Author:		Dennis Jayvee Patricio (ddpatricio)
-- Create date: 06/02/2025 12:00:00 AM
-- Description:	Insert Policy Deductibles
-- =============================================

CREATE PROCEDURE [Transaction].[PostPolicyDeductibles]
	@PolicyId bigint,
	@PolicyTypeId bigint,
	@DeductiblesId bigint,
    @Amount decimal(18,2),
	@UserId bigint
AS
BEGIN
	SET NOCOUNT ON;

	BEGIN TRY
		BEGIN TRANSACTION;

		DECLARE @ProductsId BIGINT;

		SELECT @ProductsId =
			CASE 
				WHEN @PolicyTypeId = 1 THEN (SELECT ProductsId FROM [Transaction].[IndividualPolicy] WHERE [Id] = @PolicyId AND IsDeleted = 0)
				WHEN @PolicyTypeId = 2 THEN (SELECT ProductsId FROM [Transaction].[PartnerPolicy] WHERE [Id] = @PolicyId AND IsDeleted = 0)
				WHEN @PolicyTypeId = 3 THEN (SELECT ProductsId FROM [Transaction].[GroupPolicy] WHERE [Id] = @PolicyId AND IsDeleted = 0)
			END;

		IF @ProductsId IS NULL
		BEGIN
			RAISERROR ('CustomSQLException: Policy not found.', 16, 1);
			RETURN;
		END

		IF NOT EXISTS (
			SELECT 1 
			FROM [Reference].[ProductDeductibles] 
			WHERE ProductsId = @ProductsId AND DeductiblesId = @DeductiblesId AND IsDeleted = 0
		)
		BEGIN
			RAISERROR ('CustomSQLException: Deductibles does not exist in the product.', 16, 1);
			RETURN;
		END

		DECLARE @CurrentDateTime datetime2(7) = GETUTCDATE();
		DECLARE @PolicyDeductiblesId BIGINT;

		IF EXISTS (SELECT 1 FROM [Transaction].[PolicyDeductibles] WHERE [PolicyId] = @PolicyId AND [DeductiblesId] = @DeductiblesId AND [PolicyTypeId] = @PolicyTypeId AND IsDeleted = 0)
		BEGIN
			DECLARE @Id bigint;
			SELECT @Id = Id FROM [Transaction].[PolicyDeductibles] WHERE [PolicyId] = @PolicyId AND [DeductiblesId] = @DeductiblesId AND [PolicyTypeId] = @PolicyTypeId AND IsDeleted = 0;

			UPDATE [Transaction].[PolicyDeductibles]
			SET 
				[Amount] = @Amount,
				[ModifiedBy] = @UserId,
				[ModifiedDateTime] = @CurrentDateTime
			WHERE 
				[Id] = @Id;

			SET @PolicyDeductiblesId = @Id;
		END
		ELSE
		BEGIN
			INSERT INTO [Transaction].[PolicyDeductibles]
				([PolicyId]
				,[PolicyTypeId]
				,[DeductiblesId]
				,[Amount]
				,[CreatedBy]
				,[CreatedDateTime]
				,[ModifiedBy]
				,[ModifiedDateTime])
			VALUES
				(@PolicyId
				,@PolicyTypeId
				,@DeductiblesId
				,@Amount
				,@UserId
				,@CurrentDateTime
				,@UserId
				,@CurrentDateTime)
			SET @PolicyDeductiblesId = SCOPE_IDENTITY();
		END

		--Update Reference
		--Individual
		IF @PolicyTypeId = 1
			UPDATE [Transaction].[IndividualPolicy] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @PolicyId;

		--Partner
		ELSE IF @PolicyTypeId = 2
			UPDATE [Transaction].[PartnerPolicy] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @PolicyId;

		--Group
		ELSE
			UPDATE [Transaction].[GroupPolicy] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @PolicyId;
		
		SELECT CAST(@PolicyDeductiblesId AS BIGINT) AS Id;

		COMMIT;
	END TRY
	BEGIN CATCH
		IF @@TRANCOUNT > 0
			ROLLBACK;
		THROW;
	END CATCH
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- Author:		Dennis Jayvee Patricio (ddpatricio)
-- Create date: 06/02/2025 12:00:00 AM
-- Description:	Insert Policy Benefits
-- =============================================

CREATE PROCEDURE [Transaction].[PostPolicyBenefits]
	@PolicyId bigint,
	@PolicyTypeId bigint,
	@BenefitsId bigint,
    @CoverageAmount decimal(18,2),
    @PremiumAmount decimal(18,2),
    @PremiumCommissionAmount decimal(18,2),
	@UserId bigint
AS
BEGIN
	SET NOCOUNT ON;

	BEGIN TRY
		BEGIN TRANSACTION;

		DECLARE @ProductsId BIGINT;

		SELECT @ProductsId =
			CASE 
				WHEN @PolicyTypeId = 1 THEN (SELECT ProductsId FROM [Transaction].[IndividualPolicy] WHERE [Id] = @PolicyId AND IsDeleted = 0)
				WHEN @PolicyTypeId = 2 THEN (SELECT ProductsId FROM [Transaction].[PartnerPolicy] WHERE [Id] = @PolicyId AND IsDeleted = 0)
				WHEN @PolicyTypeId = 3 THEN (SELECT ProductsId FROM [Transaction].[GroupPolicy] WHERE [Id] = @PolicyId AND IsDeleted = 0)
			END;

		IF @ProductsId IS NULL
		BEGIN
			RAISERROR ('CustomSQLException: Policy not found.', 16, 1);
			RETURN;
		END

		IF NOT EXISTS (
			SELECT 1 
			FROM [Reference].[ProductBenefits] 
			WHERE ProductsId = @ProductsId AND BenefitsId = @BenefitsId AND IsDeleted = 0
		)
		BEGIN
			RAISERROR ('CustomSQLException: Benefit does not exist in the product.', 16, 1);
			RETURN;
		END

		DECLARE @CurrentDateTime datetime2(7) = GETUTCDATE();
		DECLARE @PolicyBenefitsId BIGINT;

		IF EXISTS (SELECT 1 FROM [Transaction].[PolicyBenefits] WHERE [PolicyId] = @PolicyId AND [PolicyTypeId] = @PolicyTypeId AND [BenefitsId] = @BenefitsId AND IsDeleted = 0)
		BEGIN
			DECLARE @Id bigint;
			SELECT @Id = Id FROM [Transaction].[PolicyBenefits] WHERE [PolicyId] = @PolicyId AND [PolicyTypeId] = @PolicyTypeId AND [BenefitsId] = @BenefitsId AND IsDeleted = 0;

			UPDATE [Transaction].[PolicyBenefits]
			SET 
				[CoverageAmount] = @CoverageAmount,
				[PremiumAmount] = @PremiumAmount,
				[PremiumCommissionAmount] = @PremiumCommissionAmount,
				[ModifiedBy] = @UserId,
				[ModifiedDateTime] = @CurrentDateTime
			WHERE 
				[Id] = @Id;

			SET @PolicyBenefitsId = @Id;
		END
		ELSE
		BEGIN
			INSERT INTO [Transaction].[PolicyBenefits]
				([PolicyId]
				,[PolicyTypeId]
				,[BenefitsId]
				,[CoverageAmount]
				,[PremiumAmount]
				,[PremiumCommissionAmount]
				,[CreatedBy]
				,[CreatedDateTime]
				,[ModifiedBy]
				,[ModifiedDateTime])
			VALUES
				(@PolicyId
				,@PolicyTypeId
				,@BenefitsId
				,@CoverageAmount
				,@PremiumAmount
				,@PremiumCommissionAmount
				,@UserId
				,@CurrentDateTime
				,@UserId
				,@CurrentDateTime)
			SET @PolicyBenefitsId = SCOPE_IDENTITY();
		END

		--Update Reference
		--Check Totals
		DECLARE @TotalPaid decimal(18,2) = 0;
		SELECT @TotalPaid = ISNULL(SUM([Amount]), 0) FROM [Transaction].[PolicyPayments] WHERE [PolicyId] = @PolicyId AND [PolicyTypeId] = @PolicyTypeId AND IsDeleted = 0;

		DECLARE @TotalPremiumsBenefit decimal(18,2) = 0;
		DECLARE @TotalCoverage decimal(18,2) = 0;
		SELECT @TotalPremiumsBenefit = ISNULL(SUM([PremiumAmount]), 0), @TotalCoverage = ISNULL(SUM([CoverageAmount]), 0)
		FROM [Transaction].[PolicyBenefits] WHERE [PolicyId] = @PolicyId AND [PolicyTypeId] = @PolicyTypeId AND IsDeleted = 0;

		DECLARE @TotalPremiums decimal(18,2) = 0;
		SELECT @TotalPremiums = SUM([BasicPremium] + [DJDPatricioMarkup] + [PartnerMarkup] + [Taxes] + [DST] + [VAT] + [LGT] + [PT] + [FST] + [NotarialFee] + [Others] - [Discount])
		FROM [Transaction].[PolicyPremiums] WHERE [PolicyId] = @PolicyId AND [PolicyTypeId] = @PolicyTypeId AND IsDeleted = 0;
		SET @TotalPremiums = @TotalPremiums + @TotalPremiumsBenefit

		DECLARE @PaymentStatusId bigint;
		IF @TotalPremiums = @TotalPaid
			SET @PaymentStatusId = 1;
		IF @TotalPaid = 0
		BEGIN
			SET @PaymentStatusId = 2;
		END
		ELSE
		BEGIN
			IF @TotalPremiums > @TotalPaid
				SET @PaymentStatusId = 3;
			IF @TotalPremiums < @TotalPaid
				SET @PaymentStatusId = 5;
		END

		--Individual
		IF @PolicyTypeId = 1
			UPDATE [Transaction].[IndividualPolicy] 
			SET [PaymentStatusId] = @PaymentStatusId,
				[TotalPremium] = @TotalPremiums, 
				[TotalCoverage] = @TotalCoverage, 
				[TotalPaid] = @TotalPaid, 
				[ModifiedBy] = @UserId, 
				[ModifiedDateTime] = @CurrentDateTime 
			WHERE [Id] = @PolicyId;

		--Partner
		ELSE IF @PolicyTypeId = 2
			UPDATE [Transaction].[PartnerPolicy] 
			SET [PaymentStatusId] = @PaymentStatusId,
				[TotalPremium] = @TotalPremiums, 
				[TotalCoverage] = @TotalCoverage, 
				[TotalPaid] = @TotalPaid, 
				[ModifiedBy] = @UserId, 
				[ModifiedDateTime] = @CurrentDateTime 
			WHERE [Id] = @PolicyId;
			
		--Group
		ELSE
			UPDATE [Transaction].[GroupPolicy] 
			SET [PaymentStatusId] = @PaymentStatusId,
				[TotalPremium] = @TotalPremiums, 
				[TotalCoverage] = @TotalCoverage, 
				[TotalPaid] = @TotalPaid, 
				[ModifiedBy] = @UserId, 
				[ModifiedDateTime] = @CurrentDateTime 
			WHERE [Id] = @PolicyId;

		SELECT CAST(@PolicyBenefitsId AS BIGINT) AS Id;

		COMMIT;
	END TRY
	BEGIN CATCH
		IF @@TRANCOUNT > 0
			ROLLBACK;
		THROW;
	END CATCH
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- Author:		Dennis Jayvee Patricio (ddpatricio)
-- Create date: 06/02/2025 12:00:00 AM
-- Description:	Insert Policy Beneficiary
-- =============================================

CREATE PROCEDURE [Transaction].[PostPolicyBeneficiary]
	@PolicyId bigint,
	@PolicyTypeId bigint,
    @FirstName nvarchar(60),
    @MiddleName nvarchar(60) = NULL,
    @LastName nvarchar(60),
    @Suffix nvarchar(10) = NULL,
    @EmailAddress nvarchar(100),
    @ContactNumber nvarchar(20),
    @DateOfBirth date,
    @Relationship bigint,
	@UserId bigint
AS
BEGIN
	SET NOCOUNT ON;

	BEGIN TRY
		BEGIN TRANSACTION;

		DECLARE @FullName nvarchar(200);
		DECLARE @MiddleInitial nvarchar(5);

		IF @MiddleName IS NOT NULL AND LTRIM(RTRIM(@MiddleName)) <> ''
		BEGIN
			SET @MiddleInitial = SUBSTRING(LTRIM(RTRIM(@MiddleName)), 1, 1) + '.';
		END
		ELSE
		BEGIN
			SET @MiddleInitial = '';
		END

		SET @FullName = LTRIM(RTRIM(
						COALESCE(@FirstName, '') +
						CASE WHEN @MiddleInitial <> '' THEN ' ' + @MiddleInitial ELSE '' END +
						CASE WHEN @LastName IS NOT NULL AND @LastName <> '' THEN ' ' + @LastName ELSE '' END +
						CASE WHEN @Suffix IS NOT NULL AND @Suffix <> '' THEN ' ' + @Suffix ELSE '' END
					));

		IF EXISTS (SELECT 1 FROM [Transaction].[PolicyBeneficiary] WHERE FullName = @FullName AND PolicyId = @PolicyId AND PolicyTypeId = @PolicyTypeId AND IsDeleted = 0)
		BEGIN
			RAISERROR ('CustomSQLException: Beneficiary already exists.', 16, 1);
			RETURN;
		END

		IF (
			(@PolicyTypeId = 1 AND NOT EXISTS (SELECT 1 FROM [Transaction].[IndividualPolicy] WHERE [Id] = @PolicyId AND IsDeleted = 0)) OR
			(@PolicyTypeId = 2 AND NOT EXISTS (SELECT 1 FROM [Transaction].[PartnerPolicy] WHERE [Id] = @PolicyId AND IsDeleted = 0)) OR
			(@PolicyTypeId = 3 AND NOT EXISTS (SELECT 1 FROM [Transaction].[GroupPolicy] WHERE [Id] = @PolicyId AND IsDeleted = 0))
		)
		BEGIN
			RAISERROR ('CustomSQLException: Policy not found.', 16, 1);
			RETURN;
		END

		DECLARE @CurrentDateTime datetime2(7) = GETUTCDATE();

		INSERT INTO [Transaction].[PolicyBeneficiary]
			([PolicyId]
			,[PolicyTypeId]
			,[FirstName]
			,[MiddleName]
			,[LastName]
			,[Suffix]
			,[FullName]
			,[EmailAddress]
			,[ContactNumber]
			,[DateOfBirth]
			,[Relationship]
			,[CreatedBy]
			,[CreatedDateTime]
			,[ModifiedBy]
			,[ModifiedDateTime])
		VALUES
			(@PolicyId
			,@PolicyTypeId
			,@FirstName
			,@MiddleName
			,@LastName
			,@Suffix
			,@FullName
			,@EmailAddress
			,@ContactNumber
			,@DateOfBirth
			,@Relationship
			,@UserId
			,@CurrentDateTime
			,@UserId
			,@CurrentDateTime)
		DECLARE @PolicyBeneficiaryId BIGINT = SCOPE_IDENTITY();

		--Update Reference
		--Individual
		IF @PolicyTypeId = 1
			UPDATE [Transaction].[IndividualPolicy] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @PolicyId;

		--Partner
		ELSE IF @PolicyTypeId = 2
			UPDATE [Transaction].[PartnerPolicy] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @PolicyId;

		--Group
		ELSE
			UPDATE [Transaction].[GroupPolicy] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @PolicyId;
		
		SELECT CAST(@PolicyBeneficiaryId AS BIGINT) AS Id;

		COMMIT;
	END TRY
	BEGIN CATCH
		IF @@TRANCOUNT > 0
			ROLLBACK;
		THROW;
	END CATCH
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

