-- Description:	Insert Partner Policy
-- =============================================

CREATE PROCEDURE [Transaction].[PostPartnerPolicy]
    @PartnersId bigint,
	@PlatformsId bigint,
    @PolicyBookingStatusId bigint,
    @CocStatusId bigint,
    @ClaimsStatusId bigint,
    @AgentsId bigint,
    @SubAgentsId bigint = NULL,
    @ApproversId bigint,
	@PromoManagersId bigint = NULL,
	@SalesManagersId bigint = NULL,
	@PromoOfficersId bigint = NULL,
    @ProductsId bigint,
    @ProvidersId bigint,
    @DistributionChannelId bigint,
    @PaymentOptionId bigint,
    @ProviderPolicyNo nvarchar(50),
    @EndorsementNo nvarchar(50) = NULL,
    @TerminationDate date,
    @EffectiveDate date,
    @IssueDate date,
    @Remarks nvarchar(500) = NULL,

	--Premiums
	@BasicPremium decimal(18,2),
    @BasicPremiumCommission decimal(18,2),
    @DJDPatricioMarkup decimal(18,2),
    @PartnerMarkup decimal(18,2),
    @Discount decimal(18,2),
    @Taxes decimal(18,2),
    @DST decimal(18,2),
    @VAT decimal(18,2),
    @LGT decimal(18,2),
    @PT decimal(18,2),
    @FST decimal(18,2),
    @NotarialFee decimal(18,2),
    @Others decimal(18,2),
	@PremiumsRemarks nvarchar(500) = NULL,

	@UserId bigint
AS
BEGIN
	SET NOCOUNT ON;

	BEGIN TRY
		BEGIN TRANSACTION;

		-- Check Provider Policy No
		DECLARE @PolicyTypes TABLE (SourceTable NVARCHAR(20), CocNumber NVARCHAR(15));
		INSERT INTO @PolicyTypes (SourceTable, CocNumber)
		SELECT 'Individual', CocNumber FROM [Transaction].[IndividualPolicy] WHERE ProviderPolicyNo = @ProviderPolicyNo AND IsDeleted = 0
		UNION ALL
		SELECT 'Group', CocNumber FROM [Transaction].[GroupPolicy] WHERE ProviderPolicyNo = @ProviderPolicyNo AND IsDeleted = 0
		UNION ALL
		SELECT 'Partner', CocNumber FROM [Transaction].[PartnerPolicy] WHERE ProviderPolicyNo = @ProviderPolicyNo AND IsDeleted = 0;
		IF EXISTS (SELECT 1 FROM @PolicyTypes)
		BEGIN
			IF @EndorsementNo IS NOT NULL
			BEGIN
				-- Check if ProviderPolicyNo + EndorsementNo combination exists
				DELETE FROM @PolicyTypes;
				INSERT INTO @PolicyTypes (SourceTable, CocNumber)
				SELECT 'Individual', CocNumber FROM [Transaction].[IndividualPolicy] WHERE ProviderPolicyNo = @ProviderPolicyNo AND EndorsementNo = @EndorsementNo AND IsDeleted = 0
				UNION ALL
				SELECT 'Group', CocNumber FROM [Transaction].[GroupPolicy] WHERE ProviderPolicyNo = @ProviderPolicyNo AND EndorsementNo = @EndorsementNo AND IsDeleted = 0
				UNION ALL
				SELECT 'Partner', CocNumber FROM [Transaction].[PartnerPolicy] WHERE ProviderPolicyNo = @ProviderPolicyNo AND EndorsementNo = @EndorsementNo AND IsDeleted = 0;

				IF EXISTS (SELECT 1 FROM @PolicyTypes)
				BEGIN
					DECLARE @SourceTable1 NVARCHAR(20), @CocNumber1 NVARCHAR(15);
					SELECT TOP 1 @SourceTable1 = SourceTable, @CocNumber1 = CocNumber FROM @PolicyTypes;
					RAISERROR ('CustomSQLException: The entered Provider Policy and Endorsement Number combination already exists with %s COC Number %s. Please ensure at least one of these details is unique before proceeding.', 16, 1, @SourceTable1, @CocNumber1);
					RETURN;
				END
			END
			ELSE
			BEGIN
				DECLARE @SourceTable2 NVARCHAR(20), @CocNumber2 NVARCHAR(15);
				SELECT TOP 1 @SourceTable2 = SourceTable, @CocNumber2 = CocNumber FROM @PolicyTypes;
				RAISERROR ('CustomSQLException: Provider Policy is currently used by %s COC Number %s. Please enter the Endorsement Number to verify its validity.', 16, 1, @SourceTable2, @CocNumber2);
				RETURN;
			END
		END

		--Generate Reference Number
		DECLARE @ReferenceNumber VARCHAR(12);
		SELECT @ReferenceNumber = 'PPB' + RIGHT('000000000' + 
			CAST(ISNULL(MAX(CAST(SUBSTRING(ReferenceNumber, 4, 9) AS INT)), 0) + 1 AS VARCHAR), 9)
		FROM [Transaction].[GroupPolicy];

		--Generate COC Number
		DECLARE @CocNumber VARCHAR(12);
		SELECT @CocNumber = RIGHT('000000000000' + CAST(
		ISNULL((
			SELECT MAX(MaxNumber) + 1
			FROM (
				SELECT MAX(CAST(SUBSTRING(CocNumber, 1, 12) AS BIGINT)) AS MaxNumber FROM [Transaction].[IndividualPolicy]
				UNION ALL
				SELECT MAX(CAST(SUBSTRING(CocNumber, 1, 12) AS BIGINT)) FROM [Transaction].[GroupPolicy]
				UNION ALL
				SELECT MAX(CAST(SUBSTRING(CocNumber, 1, 12) AS BIGINT)) FROM [Transaction].[PartnerPolicy]
			) AS AllMax
		), 1) AS VARCHAR), 12);

		DECLARE @CurrentDateTime datetime2(7) = GETUTCDATE();

		INSERT INTO [Transaction].[PartnerPolicy]
			([ReferenceNumber]
			,[CocNumber]
			,[PartnersId]
			,[PlatformsId]
			,[PolicyBookingStatusId]
			,[CocStatusId]
			,[PaymentStatusId]
			,[ClaimsStatusId]
			,[AgentsId]
			,[SubAgentsId]
			,[ApproversId]
			,[PromoManagersId]
			,[SalesManagersId]
			,[PromoOfficersId]
			,[ProductsId]
			,[ProvidersId]
			,[DistributionChannelId]
			,[PaymentOptionId]
			,[ProviderPolicyNo]
			,[EndorsementNo]
			,[TerminationDate]
			,[EffectiveDate]
			,[IssueDate]
			,[Remarks]
			,[CreatedBy]
			,[CreatedDateTime]
			,[ModifiedBy]
			,[ModifiedDateTime])
		VALUES
			(@ReferenceNumber
			,@CocNumber
			,@PartnersId
			,@PlatformsId
			,@PolicyBookingStatusId
			,@CocStatusId
			,2
			,@ClaimsStatusId
			,@AgentsId
			,@SubAgentsId
			,@ApproversId
			,@PromoManagersId
			,@SalesManagersId
			,@PromoOfficersId
			,@ProductsId
			,@ProvidersId
			,@DistributionChannelId
			,@PaymentOptionId
			,@ProviderPolicyNo
			,@EndorsementNo
			,@TerminationDate
			,@EffectiveDate
			,@IssueDate
			,@Remarks
			,@UserId
			,@CurrentDateTime
			,@UserId
			,@CurrentDateTime)

		DECLARE @PolicyId BIGINT = SCOPE_IDENTITY();

		INSERT INTO [Transaction].[PolicyPremiums]
			([PolicyId]
			,[PolicyTypeId]
			,[BasicPremium]
			,[BasicPremiumCommission]
			,[DJDPatricioMarkup]
			,[PartnerMarkup]
			,[Discount]
			,[Taxes]
			,[DST]
			,[VAT]
			,[LGT]
			,[PT]
			,[FST]
			,[NotarialFee]
			,[Others]
			,[Remarks]
			,[CreatedBy]
			,[CreatedDateTime]
			,[ModifiedBy]
			,[ModifiedDateTime])
		VALUES
			(@PolicyId
			,2
			,@BasicPremium
			,@BasicPremiumCommission
			,@DJDPatricioMarkup
			,@PartnerMarkup
			,@Discount
			,@Taxes
			,@DST
			,@VAT
			,@LGT
			,@PT
			,@FST
			,@NotarialFee
			,@Others
			,@PremiumsRemarks
			,@UserId
			,@CurrentDateTime
			,@UserId
			,@CurrentDateTime)

		--Update Reference
		--Check Totals
		DECLARE @TotalPaid decimal(18,2) = 0;
		SELECT @TotalPaid = ISNULL(SUM([Amount]), 0) FROM [Transaction].[PolicyPayments] WHERE [PolicyId] = @PolicyId AND [PolicyTypeId] = 2 AND IsDeleted = 0;

		DECLARE @TotalPremiumsBenefit decimal(18,2) = 0;
		DECLARE @TotalCoverage decimal(18,2) = 0;
		SELECT @TotalPremiumsBenefit = ISNULL(SUM([PremiumAmount]), 0), @TotalCoverage = ISNULL(SUM([CoverageAmount]), 0)
		FROM [Transaction].[PolicyBenefits] WHERE [PolicyId] = @PolicyId AND [PolicyTypeId] = 2 AND IsDeleted = 0;

		DECLARE @TotalPremiums decimal(18,2) = 0;
		SELECT @TotalPremiums = SUM([BasicPremium] + [DJDPatricioMarkup] + [PartnerMarkup] + [Taxes] + [DST] + [VAT] + [LGT] + [PT] + [FST] + [NotarialFee] + [Others] - [Discount])
		FROM [Transaction].[PolicyPremiums] WHERE [PolicyId] = @PolicyId AND [PolicyTypeId] = 2 AND IsDeleted = 0;
		SET @TotalPremiums = @TotalPremiums + @TotalPremiumsBenefit

		DECLARE @PaymentStatusId bigint;
		IF @TotalPremiums = @TotalPaid
			SET @PaymentStatusId = 1;
		IF @TotalPaid = 0
		BEGIN
			SET @PaymentStatusId = 2;
		END
		ELSE
		BEGIN
			IF @TotalPremiums > @TotalPaid
				SET @PaymentStatusId = 3;
			IF @TotalPremiums < @TotalPaid
				SET @PaymentStatusId = 5;
		END

		--Partner
		UPDATE [Transaction].[PartnerPolicy] 
		SET [PaymentStatusId] = @PaymentStatusId,
			[TotalPremium] = @TotalPremiums, 
			[TotalCoverage] = @TotalCoverage, 
			[TotalPaid] = @TotalPaid
		WHERE [Id] = @PolicyId;

		SELECT CAST(@PolicyId AS BIGINT) AS Id;

		COMMIT;
	END TRY
	BEGIN CATCH
		IF @@TRANCOUNT > 0
			ROLLBACK;
		THROW;
	END CATCH
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- Author:		Dennis Jayvee Patricio (ddpatricio)
-- Create date: 06/02/2025 12:00:00 AM
-- Description:	Insert Individual Policy
-- =============================================

CREATE PROCEDURE [Transaction].[PostIndividualPolicy]
    @ClientsId bigint,
    @PartnersId bigint,
	@PlatformsId bigint,
    @PolicyBookingStatusId bigint,
    @CocStatusId bigint,
    @ClaimsStatusId bigint,
    @AgentsId bigint,
    @SubAgentsId bigint = NULL,
    @ApproversId bigint,
	@PromoManagersId bigint = NULL,
	@SalesManagersId bigint = NULL,
	@PromoOfficersId bigint = NULL,
    @ProductsId bigint,
    @ProvidersId bigint,
    @DistributionChannelId bigint,
    @PaymentOptionId bigint,
    @ProviderPolicyNo nvarchar(50),
    @EndorsementNo nvarchar(50) = NULL,
    @TerminationDate date,
    @EffectiveDate date,
    @IssueDate date,
    @Remarks nvarchar(500) = NULL,

	--Premiums
	@BasicPremium decimal(18,2),
    @BasicPremiumCommission decimal(18,2),
    @DJDPatricioMarkup decimal(18,2),
    @PartnerMarkup decimal(18,2),
    @Discount decimal(18,2),
    @Taxes decimal(18,2),
    @DST decimal(18,2),
    @VAT decimal(18,2),
    @LGT decimal(18,2),
    @PT decimal(18,2),
    @FST decimal(18,2),
    @NotarialFee decimal(18,2),
    @Others decimal(18,2),
	@PremiumsRemarks nvarchar(500) = NULL,

	@UserId bigint
AS
BEGIN
	SET NOCOUNT ON;

	BEGIN TRY
		BEGIN TRANSACTION;

		-- Check Provider Policy No
		DECLARE @PolicyTypes TABLE (SourceTable NVARCHAR(20), CocNumber NVARCHAR(15));
		INSERT INTO @PolicyTypes (SourceTable, CocNumber)
		SELECT 'Individual', CocNumber FROM [Transaction].[IndividualPolicy] WHERE ProviderPolicyNo = @ProviderPolicyNo AND IsDeleted = 0
		UNION ALL
		SELECT 'Group', CocNumber FROM [Transaction].[GroupPolicy] WHERE ProviderPolicyNo = @ProviderPolicyNo AND IsDeleted = 0
		UNION ALL
		SELECT 'Partner', CocNumber FROM [Transaction].[PartnerPolicy] WHERE ProviderPolicyNo = @ProviderPolicyNo AND IsDeleted = 0;
		IF EXISTS (SELECT 1 FROM @PolicyTypes)
		BEGIN
			IF @EndorsementNo IS NOT NULL
			BEGIN
				-- Check if ProviderPolicyNo + EndorsementNo combination exists
				DELETE FROM @PolicyTypes;
				INSERT INTO @PolicyTypes (SourceTable, CocNumber)
				SELECT 'Individual', CocNumber FROM [Transaction].[IndividualPolicy] WHERE ProviderPolicyNo = @ProviderPolicyNo AND EndorsementNo = @EndorsementNo AND IsDeleted = 0
				UNION ALL
				SELECT 'Group', CocNumber FROM [Transaction].[GroupPolicy] WHERE ProviderPolicyNo = @ProviderPolicyNo AND EndorsementNo = @EndorsementNo AND IsDeleted = 0
				UNION ALL
				SELECT 'Partner', CocNumber FROM [Transaction].[PartnerPolicy] WHERE ProviderPolicyNo = @ProviderPolicyNo AND EndorsementNo = @EndorsementNo AND IsDeleted = 0;

				IF EXISTS (SELECT 1 FROM @PolicyTypes)
				BEGIN
					DECLARE @SourceTable1 NVARCHAR(20), @CocNumber1 NVARCHAR(15);
					SELECT TOP 1 @SourceTable1 = SourceTable, @CocNumber1 = CocNumber FROM @PolicyTypes;
					RAISERROR ('CustomSQLException: The entered Provider Policy and Endorsement Number combination already exists with %s COC Number %s. Please ensure at least one of these details is unique before proceeding.', 16, 1, @SourceTable1, @CocNumber1);
					RETURN;
				END
			END
			ELSE
			BEGIN
				DECLARE @SourceTable2 NVARCHAR(20), @CocNumber2 NVARCHAR(15);
				SELECT TOP 1 @SourceTable2 = SourceTable, @CocNumber2 = CocNumber FROM @PolicyTypes;
				RAISERROR ('CustomSQLException: Provider Policy is currently used by %s COC Number %s. Please enter the Endorsement Number to verify its validity.', 16, 1, @SourceTable2, @CocNumber2);
				RETURN;
			END
		END

		--Generate Reference Number
		DECLARE @ReferenceNumber VARCHAR(12);
		SELECT @ReferenceNumber = 'IPB' + RIGHT('000000000' + 
			CAST(ISNULL(MAX(CAST(SUBSTRING(ReferenceNumber, 4, 9) AS INT)), 0) + 1 AS VARCHAR), 9)
		FROM [Transaction].[GroupPolicy];

		--Generate COC Number
		DECLARE @CocNumber VARCHAR(12);
		SELECT @CocNumber = RIGHT('000000000000' + CAST(
		ISNULL((
			SELECT MAX(MaxNumber) + 1
			FROM (
				SELECT MAX(CAST(SUBSTRING(CocNumber, 1, 12) AS BIGINT)) AS MaxNumber FROM [Transaction].[IndividualPolicy]
				UNION ALL
				SELECT MAX(CAST(SUBSTRING(CocNumber, 1, 12) AS BIGINT)) FROM [Transaction].[GroupPolicy]
				UNION ALL
				SELECT MAX(CAST(SUBSTRING(CocNumber, 1, 12) AS BIGINT)) FROM [Transaction].[PartnerPolicy]
			) AS AllMax
		), 1) AS VARCHAR), 12);

		DECLARE @CurrentDateTime datetime2(7) = GETUTCDATE();

		INSERT INTO [Transaction].[IndividualPolicy]
			([ReferenceNumber]
			,[CocNumber]
			,[ClientsId]
			,[PartnersId]
			,[PlatformsId]
			,[PolicyBookingStatusId]
			,[CocStatusId]
			,[PaymentStatusId]
			,[ClaimsStatusId]
			,[AgentsId]
			,[SubAgentsId]
			,[ApproversId]
			,[PromoManagersId]
			,[SalesManagersId]
			,[PromoOfficersId]
			,[ProductsId]
			,[ProvidersId]
			,[DistributionChannelId]
			,[PaymentOptionId]
			,[ProviderPolicyNo]
			,[EndorsementNo]
			,[TerminationDate]
			,[EffectiveDate]
			,[IssueDate]
			,[Remarks]
			,[CreatedBy]
			,[CreatedDateTime]
			,[ModifiedBy]
			,[ModifiedDateTime])
		VALUES
			(@ReferenceNumber
			,@CocNumber
			,@ClientsId
			,@PartnersId
			,@PlatformsId
			,@PolicyBookingStatusId
			,@CocStatusId
			,2
			,@ClaimsStatusId
			,@AgentsId
			,@SubAgentsId
			,@ApproversId
			,@PromoManagersId
			,@SalesManagersId
			,@PromoOfficersId
			,@ProductsId
			,@ProvidersId
			,@DistributionChannelId
			,@PaymentOptionId
			,@ProviderPolicyNo
			,@EndorsementNo
			,@TerminationDate
			,@EffectiveDate
			,@IssueDate
			,@Remarks
			,@UserId
			,@CurrentDateTime
			,@UserId
			,@CurrentDateTime)

		DECLARE @PolicyId BIGINT = SCOPE_IDENTITY();

		INSERT INTO [Transaction].[PolicyPremiums]
			([PolicyId]
			,[PolicyTypeId]
			,[BasicPremium]
			,[BasicPremiumCommission]
			,[DJDPatricioMarkup]
			,[PartnerMarkup]
			,[Discount]
			,[Taxes]
			,[DST]
			,[VAT]
			,[LGT]
			,[PT]
			,[FST]
			,[NotarialFee]
			,[Others]
			,[Remarks]
			,[CreatedBy]
			,[CreatedDateTime]
			,[ModifiedBy]
			,[ModifiedDateTime])
		VALUES
			(@PolicyId
			,1
			,@BasicPremium
			,@BasicPremiumCommission
			,@DJDPatricioMarkup
			,@PartnerMarkup
			,@Discount
			,@Taxes
			,@DST
			,@VAT
			,@LGT
			,@PT
			,@FST
			,@NotarialFee
			,@Others
			,@PremiumsRemarks
			,@UserId
			,@CurrentDateTime
			,@UserId
			,@CurrentDateTime)

		--Update Reference
		--Check Totals
		DECLARE @TotalPaid decimal(18,2) = 0;
		SELECT @TotalPaid = ISNULL(SUM([Amount]), 0) FROM [Transaction].[PolicyPayments] WHERE [PolicyId] = @PolicyId AND [PolicyTypeId] = 1 AND IsDeleted = 0;

		DECLARE @TotalPremiumsBenefit decimal(18,2) = 0;
		DECLARE @TotalCoverage decimal(18,2) = 0;
		SELECT @TotalPremiumsBenefit = ISNULL(SUM([PremiumAmount]), 0), @TotalCoverage = ISNULL(SUM([CoverageAmount]), 0)
		FROM [Transaction].[PolicyBenefits] WHERE [PolicyId] = @PolicyId AND [PolicyTypeId] = 1 AND IsDeleted = 0;

		DECLARE @TotalPremiums decimal(18,2) = 0;
		SELECT @TotalPremiums = SUM([BasicPremium] + [DJDPatricioMarkup] + [PartnerMarkup] + [Taxes] + [DST] + [VAT] + [LGT] + [PT] + [FST] + [NotarialFee] + [Others] - [Discount])
		FROM [Transaction].[PolicyPremiums] WHERE [PolicyId] = @PolicyId AND [PolicyTypeId] = 1 AND IsDeleted = 0;
		SET @TotalPremiums = @TotalPremiums + @TotalPremiumsBenefit

		DECLARE @PaymentStatusId bigint;
		IF @TotalPremiums = @TotalPaid
			SET @PaymentStatusId = 1;
		IF @TotalPaid = 0
		BEGIN
			SET @PaymentStatusId = 2;
		END
		ELSE
		BEGIN
			IF @TotalPremiums > @TotalPaid
				SET @PaymentStatusId = 3;
			IF @TotalPremiums < @TotalPaid
				SET @PaymentStatusId = 5;
		END

		--Individual
		UPDATE [Transaction].[IndividualPolicy] 
		SET [PaymentStatusId] = @PaymentStatusId,
			[TotalPremium] = @TotalPremiums, 
			[TotalCoverage] = @TotalCoverage, 
			[TotalPaid] = @TotalPaid
		WHERE [Id] = @PolicyId;

		SELECT CAST(@PolicyId AS BIGINT) AS Id;

		COMMIT;
	END TRY
	BEGIN CATCH
		IF @@TRANCOUNT > 0
			ROLLBACK;
		THROW;
	END CATCH
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

