-- =============================================
-- Author:		Dennis Jayvee Patricio (ddpatricio)
-- Create date: 06/02/2025 12:00:00 AM
-- Description:	Insert Attachments
-- =============================================

CREATE PROCEDURE [Transaction].[PostAttachments]
	@ReferenceId bigint,
	@AttachmentTypeId bigint,
	@ContentType nvarchar(200) = NULL,
    @FileName nvarchar(max),
    @Attachment varbinary(max),
	@UserId bigint
AS
BEGIN
	SET NOCOUNT ON;

	BEGIN TRY
		BEGIN TRANSACTION;

		IF (
			(@AttachmentTypeId = 1 AND NOT EXISTS (SELECT 1 FROM [Transaction].[IndividualPolicy] WHERE [Id] = @ReferenceId AND IsDeleted = 0)) OR
			(@AttachmentTypeId = 2 AND NOT EXISTS (SELECT 1 FROM [Transaction].[PartnerPolicy] WHERE [Id] = @ReferenceId AND IsDeleted = 0)) OR
			(@AttachmentTypeId IN (3, 4) AND NOT EXISTS (SELECT 1 FROM [Transaction].[GroupPolicy] WHERE [Id] = @ReferenceId AND IsDeleted = 0)) OR
			(@AttachmentTypeId NOT IN (1, 2, 3, 4) AND NOT EXISTS (SELECT 1 FROM [Transaction].[PolicyPayments] WHERE [Id] = @ReferenceId AND IsDeleted = 0))
		)
		BEGIN
			RAISERROR ('CustomSQLException: Reference not found.', 16, 1);
			RETURN;
		END

		DECLARE @CurrentDateTime datetime2(7) = GETUTCDATE();

		INSERT INTO [Transaction].[Attachments]
			([ReferenceId]
			,[AttachmentTypeId]
			,[ContentType]
			,[FileName]
			,[Attachment]
			,[CreatedBy]
			,[CreatedDateTime]
			,[ModifiedBy]
			,[ModifiedDateTime])
		VALUES
			(@ReferenceId
			,@AttachmentTypeId
			,@ContentType
			,@FileName
			,@Attachment
			,@UserId
			,@CurrentDateTime
			,@UserId
			,@CurrentDateTime)
		DECLARE @PolicyPaymentsId BIGINT = SCOPE_IDENTITY();

		--Update Reference
		IF @AttachmentTypeId IN (1, 2, 3, 4)
		BEGIN
			--Individual
			IF @AttachmentTypeId = 1
				UPDATE [Transaction].[IndividualPolicy] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @ReferenceId;

			--Partner
			ELSE IF @AttachmentTypeId = 2
				UPDATE [Transaction].[PartnerPolicy] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @ReferenceId;

			--Group Policy Copy or DeclarationFile
			ELSE
				UPDATE [Transaction].[GroupPolicy] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @ReferenceId;
		END
		ELSE
		BEGIN
			--Payments
			UPDATE [Transaction].[PolicyPayments] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @ReferenceId;

			DECLARE @PolicyTypeId BIGINT = NULL;
			DECLARE @PolicyId BIGINT = NULL;
			SELECT @PolicyTypeId = PolicyTypeId, @PolicyId = PolicyId FROM [Transaction].[PolicyPayments] WHERE [Id] = @ReferenceId;

			--Update Reference
			--Individual
			IF @PolicyTypeId = 1
				UPDATE [Transaction].[IndividualPolicy] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @PolicyId;

			--Partner
			ELSE IF @PolicyTypeId = 2
				UPDATE [Transaction].[PartnerPolicy] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @PolicyId;

			--Group
			ELSE
				UPDATE [Transaction].[GroupPolicy] SET [ModifiedBy] = @UserId, [ModifiedDateTime] = @CurrentDateTime WHERE [Id] = @PolicyId;
		END

		SELECT CAST(@PolicyPaymentsId AS BIGINT) AS Id;

		COMMIT;
	END TRY
	BEGIN CATCH
		IF @@TRANCOUNT > 0
			ROLLBACK;
		THROW;
	END CATCH
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- Author:		Dennis Jayvee Patricio (ddpatricio)
-- Create date: 06/02/2025 12:00:00 AM
-- Description:	Fetch Summary Year to Year
-- =============================================

CREATE PROCEDURE [dbo].[GetSummaryYearToYear]
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
		WITH YearlyRevenueBase AS (
    SELECT
        YEAR(T.CreatedDateTime) AS ReportingYear,
			SUM(T.TotalPaid) AS TotalRevenue
		FROM (
			SELECT [Id], [TotalPaid], [CreatedDateTime] FROM [Transaction].[GroupPolicy] WHERE IsDeleted = 0
			UNION ALL
			SELECT [Id], [TotalPaid], [CreatedDateTime] FROM [Transaction].[IndividualPolicy] WHERE IsDeleted = 0
			UNION ALL
			SELECT [Id], [TotalPaid], [CreatedDateTime] FROM [Transaction].[PartnerPolicy] WHERE IsDeleted = 0
		) AS T
		WHERE T.TotalPaid IS NOT NULL
		GROUP BY YEAR(T.CreatedDateTime)
	),
	YearlyRevenueMetrics AS (
		SELECT
			'Revenue' AS MetricName,
			yra.ReportingYear,
			yra.TotalRevenue AS CurrentYearValue,
			LAG(yra.TotalRevenue, 1, 0) OVER (ORDER BY yra.ReportingYear) AS PreviousYearValue,
			CAST(
				CASE
					WHEN LAG(yra.TotalRevenue, 1, 0) OVER (ORDER BY yra.ReportingYear) = 0 THEN
						CASE
							WHEN yra.TotalRevenue > 0 THEN yra.TotalRevenue * 100.00
							ELSE 0.00
						END
					ELSE
						ROUND(((yra.TotalRevenue - LAG(yra.TotalRevenue, 1, 0) OVER (ORDER BY yra.ReportingYear)) * 1.0 / LAG(yra.TotalRevenue, 1, 0) OVER (ORDER BY yra.ReportingYear)) * 100, 2)
				END
			AS DECIMAL(18,2)) AS PercentageIncrease,
			ROW_NUMBER() OVER (PARTITION BY 'Revenue' ORDER BY yra.ReportingYear DESC) AS rn
		FROM
			YearlyRevenueBase yra
	),
	YearlyBookingsBase AS (
		SELECT
			YEAR(T.CreatedDateTime) AS ReportingYear,
			COUNT(T.Id) AS TotalBookings
		FROM (
			SELECT [Id], [CreatedDateTime] FROM [Transaction].[GroupPolicy] WHERE IsDeleted = 0
			UNION ALL
			SELECT [Id], [CreatedDateTime] FROM [Transaction].[IndividualPolicy] WHERE IsDeleted = 0
			UNION ALL
			SELECT [Id], [CreatedDateTime] FROM [Transaction].[PartnerPolicy] WHERE IsDeleted = 0
		) AS T
		WHERE T.Id IS NOT NULL
		GROUP BY YEAR(T.CreatedDateTime)
	),
	YearlyBookingsMetrics AS (
		SELECT
			'Bookings' AS MetricName,
			yab.ReportingYear,
			yab.TotalBookings AS CurrentYearValue,
			LAG(yab.TotalBookings, 1, 0) OVER (ORDER BY yab.ReportingYear) AS PreviousYearValue,
			CAST(
				CASE
					WHEN LAG(yab.TotalBookings, 1, 0) OVER (ORDER BY yab.ReportingYear) = 0 THEN
						CASE
							WHEN yab.TotalBookings > 0 THEN yab.TotalBookings * 100.00
							ELSE 0.00
						END
					ELSE
						ROUND(((yab.TotalBookings - LAG(yab.TotalBookings, 1, 0) OVER (ORDER BY yab.ReportingYear)) * 1.0 / LAG(yab.TotalBookings, 1, 0) OVER (ORDER BY yab.ReportingYear)) * 100, 2)
				END
			AS DECIMAL(18,2)) AS PercentageIncrease,
			ROW_NUMBER() OVER (PARTITION BY 'Bookings' ORDER BY yab.ReportingYear DESC) AS rn
		FROM
			YearlyBookingsBase yab
	),
	YearlyCustomerMetrics AS (
		SELECT
			'Customers' AS MetricName,
			yacr.ReportingYear,
			yacr.TotalCustomerRecords AS CurrentYearValue,
			LAG(yacr.TotalCustomerRecords, 1, 0) OVER (ORDER BY yacr.ReportingYear) AS PreviousYearValue,
			CAST(
				CASE
					WHEN LAG(yacr.TotalCustomerRecords, 1, 0) OVER (ORDER BY yacr.ReportingYear) = 0 THEN
						CASE
							WHEN yacr.TotalCustomerRecords > 0 THEN yacr.TotalCustomerRecords * 100.00
							ELSE 0.00
						END
					ELSE
						ROUND(((yacr.TotalCustomerRecords - LAG(yacr.TotalCustomerRecords, 1, 0) OVER (ORDER BY yacr.ReportingYear)) * 1.0 / LAG(yacr.TotalCustomerRecords, 1, 0) OVER (ORDER BY yacr.ReportingYear)) * 100, 2)
				END
			AS DECIMAL(18,2)) AS PercentageIncrease,
			ROW_NUMBER() OVER (PARTITION BY 'Customers' ORDER BY yacr.ReportingYear DESC) AS rn
		FROM
			(SELECT YEAR([CreatedDateTime]) AS ReportingYear, COUNT([Id]) AS TotalCustomerRecords FROM [Reference].[Clients] WHERE [Id] IS NOT NULL AND [CreatedDateTime] IS NOT NULL AND IsDeleted = 0 GROUP BY YEAR([CreatedDateTime])) yacr
	),
	YearlyPartnerMetrics AS (
		SELECT
			'Partners' AS MetricName,
			yapr.ReportingYear,
			yapr.TotalPartnerRecords AS CurrentYearValue,
			LAG(yapr.TotalPartnerRecords, 1, 0) OVER (ORDER BY yapr.ReportingYear) AS PreviousYearValue,
			CAST(
				CASE
					WHEN LAG(yapr.TotalPartnerRecords, 1, 0) OVER (ORDER BY yapr.ReportingYear) = 0 THEN
						CASE
							WHEN yapr.TotalPartnerRecords > 0 THEN yapr.TotalPartnerRecords * 100.00
							ELSE 0.00
						END
					ELSE
						ROUND(((yapr.TotalPartnerRecords - LAG(yapr.TotalPartnerRecords, 1, 0) OVER (ORDER BY yapr.ReportingYear)) * 1.0 / LAG(yapr.TotalPartnerRecords, 1, 0) OVER (ORDER BY yapr.ReportingYear)) * 100, 2)
				END
			AS DECIMAL(18,2)) AS PercentageIncrease,
			ROW_NUMBER() OVER (PARTITION BY 'Partners' ORDER BY yapr.ReportingYear DESC) AS rn
		FROM
			(SELECT YEAR([CreatedDateTime]) AS ReportingYear, COUNT([Id]) AS TotalPartnerRecords FROM [Reference].[Partners] WHERE [Id] IS NOT NULL AND [CreatedDateTime] IS NOT NULL AND IsDeleted = 0 GROUP BY YEAR([CreatedDateTime])) yapr
	)
	SELECT
		CAST(m.Id AS INT) AS Id,
		m.MetricName,
		m.ReportingYear,
		CAST(m.CurrentYearValue AS DECIMAL(18,2)) AS CurrentYearValue,
		CAST(m.PreviousYearValue AS DECIMAL(18,2)) AS PreviousYearValue,
		m.PercentageIncrease,
		CASE
			WHEN m.PreviousYearValue = 0 AND m.CurrentYearValue > 0 THEN 'UP'
			WHEN m.PercentageIncrease > 0 THEN 'UP'
			WHEN m.PercentageIncrease < 0 THEN 'DOWN'
			ELSE 'MIDDLE'
		END AS Trend
	FROM
		(
			SELECT 1 AS Id, MetricName, ReportingYear, CurrentYearValue, PreviousYearValue, PercentageIncrease, rn FROM YearlyRevenueMetrics WHERE rn = 1
			UNION ALL
			SELECT 2 AS Id, MetricName, ReportingYear, CurrentYearValue, PreviousYearValue, PercentageIncrease, rn FROM YearlyBookingsMetrics WHERE rn = 1
			UNION ALL
			SELECT 3 AS Id, MetricName, ReportingYear, CurrentYearValue, PreviousYearValue, PercentageIncrease, rn FROM YearlyCustomerMetrics WHERE rn = 1
			UNION ALL
			SELECT 4 AS Id, MetricName, ReportingYear, CurrentYearValue, PreviousYearValue, PercentageIncrease, rn FROM YearlyPartnerMetrics WHERE rn = 1
		) AS m
	ORDER BY m.Id;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH
END;
GO
