-- =============================================

CREATE PROCEDURE [Transaction].[GetIndividualPolicy]
    @Id bigint = NULL,
    @ReferenceNumber nvarchar(15) = NULL,
    @CocNumber nvarchar(15) = NULL,
    @ClientsId bigint = NULL,
    @PartnersId bigint = NULL,
    @IssueStatus bit = NULL,
    @PolicyBookingStatusId nvarchar(MAX) = NULL,	-- Id's separated by comma
    @CocStatusId nvarchar(MAX) = NULL,				-- Id's separated by comma
    @PaymentStatusId nvarchar(MAX) = NULL,			-- Id's separated by comma
    @ClaimsStatusId nvarchar(MAX) = NULL,			-- Id's separated by comma
    @PageNumber int = 1, -- 0 For Last Page
    @PageSize int = 10 -- 0 To Fetch All
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        DECLARE @TotalCount bigint;
        DECLARE @TotalPages int;

        SELECT @TotalCount = COUNT(1)
        FROM [Transaction].[IndividualPolicy] AS [IP]
        LEFT JOIN [Transaction].[PolicyPremiums] AS [PP] ON [PP].[PolicyId] = [IP].[Id] AND [PP].[PolicyTypeId] = 1
        WHERE
            (@Id IS NULL OR [IP].[Id] = @Id)
            AND (@ReferenceNumber IS NULL OR [IP].[ReferenceNumber] = @ReferenceNumber)
            AND (@CocNumber IS NULL OR [IP].[CocNumber] = @CocNumber)
            AND (@PartnersId IS NULL OR [IP].[PartnersId] = @PartnersId)
            AND (@ClientsId IS NULL OR [IP].[ClientsId] = @ClientsId)
            AND (@IssueStatus IS NULL OR [IP].[IssueStatus] = @IssueStatus)
            AND (@PolicyBookingStatusId IS NULL OR EXISTS (SELECT 1 FROM STRING_SPLIT(@PolicyBookingStatusId, ',') WHERE TRY_CAST(value AS BIGINT) = [IP].[PolicyBookingStatusId]))
            AND (@CocStatusId IS NULL OR EXISTS (SELECT 1 FROM STRING_SPLIT(@CocStatusId, ',') WHERE TRY_CAST(value AS BIGINT) = [IP].[CocStatusId]))
            AND (@PaymentStatusId IS NULL OR EXISTS (SELECT 1 FROM STRING_SPLIT(@PaymentStatusId, ',') WHERE TRY_CAST(value AS BIGINT) = [IP].[PaymentStatusId]))
            AND (@ClaimsStatusId IS NULL OR EXISTS (SELECT 1 FROM STRING_SPLIT(@ClaimsStatusId, ',') WHERE TRY_CAST(value AS BIGINT) = [IP].[ClaimsStatusId]))
            AND [IP].[IsDeleted] = 0;

        IF @PageSize = 0
        BEGIN
            SET @PageNumber = 1;
            SET @PageSize = @TotalCount;
            IF @PageSize = 0 SET @PageSize = 1;
        END
        ELSE IF @PageNumber = 0
        BEGIN
            SET @TotalPages = CEILING(CAST(@TotalCount AS decimal) / @PageSize);
            SET @PageNumber = IIF(@TotalPages = 0, 1, @TotalPages);
        END
        ELSE IF @PageNumber < 1
        BEGIN
            SET @PageNumber = 1;
        END

        SELECT
            [IP].[Id],
            [IP].[ReferenceNumber],
            [IP].[CocNumber],
            [IP].[ClientsId],
            [IP].[PartnersId],
            [IP].[PlatformsId],
            [IP].[IssueStatus],
            [IP].[PolicyBookingStatusId],
            [IP].[CocStatusId],
            [IP].[PaymentStatusId],
            [IP].[ClaimsStatusId],
            [IP].[AgentsId],
            [IP].[SubAgentsId],
            [IP].[ApproversId],
            [IP].[PromoManagersId],
            [IP].[SalesManagersId],
            [IP].[PromoOfficersId],
            [IP].[ProductsId],
            [IP].[ProvidersId],
            [IP].[DistributionChannelId],
            [IP].[PaymentOptionId],
            [IP].[ProviderPolicyNo],
            [IP].[EndorsementNo],
            [IP].[TerminationDate],
            [IP].[EffectiveDate],
            [IP].[IssueDate],
            [IP].[Remarks],
            [IP].[TotalPremium],
            [IP].[TotalCoverage],
            [IP].[TotalPaid],
            [IP].[CreatedBy],
            [IP].[CreatedDateTime],
            [IP].[ModifiedBy],
            [IP].[ModifiedDateTime],

            --Premiums
            [PP].[BasicPremium],
            [PP].[BasicPremiumCommission],
            [PP].[DJDPatricioMarkup],
            [PP].[PartnerMarkup],
            [PP].[Discount],
            [PP].[Taxes],
            [PP].[DST],
            [PP].[VAT],
            [PP].[LGT],
            [PP].[PT],
            [PP].[FST],
            [PP].[NotarialFee],
            [PP].[Others],
            [PP].[Remarks] AS [PremiumsRemarks]
        FROM
            [Transaction].[IndividualPolicy] AS [IP]
            LEFT JOIN [Transaction].[PolicyPremiums] AS [PP] ON [PP].[PolicyId] = [IP].[Id] AND [PP].[PolicyTypeId] = 1
        WHERE
            (@Id IS NULL OR [IP].[Id] = @Id)
            AND (@ReferenceNumber IS NULL OR [IP].[ReferenceNumber] = @ReferenceNumber)
            AND (@CocNumber IS NULL OR [IP].[CocNumber] = @CocNumber)
            AND (@PartnersId IS NULL OR [IP].[PartnersId] = @PartnersId)
            AND (@ClientsId IS NULL OR [IP].[ClientsId] = @ClientsId)
            AND (@IssueStatus IS NULL OR [IP].[IssueStatus] = @IssueStatus)
            AND (@PolicyBookingStatusId IS NULL OR EXISTS (SELECT 1 FROM STRING_SPLIT(@PolicyBookingStatusId, ',') WHERE TRY_CAST(value AS BIGINT) = [IP].[PolicyBookingStatusId]))
            AND (@CocStatusId IS NULL OR EXISTS (SELECT 1 FROM STRING_SPLIT(@CocStatusId, ',') WHERE TRY_CAST(value AS BIGINT) = [IP].[CocStatusId]))
            AND (@PaymentStatusId IS NULL OR EXISTS (SELECT 1 FROM STRING_SPLIT(@PaymentStatusId, ',') WHERE TRY_CAST(value AS BIGINT) = [IP].[PaymentStatusId]))
            AND (@ClaimsStatusId IS NULL OR EXISTS (SELECT 1 FROM STRING_SPLIT(@ClaimsStatusId, ',') WHERE TRY_CAST(value AS BIGINT) = [IP].[ClaimsStatusId]))
            AND [IP].[IsDeleted] = 0
        ORDER BY
            [IP].[Id] ASC
        OFFSET (@PageNumber - 1) * @PageSize ROWS
        FETCH NEXT @PageSize ROWS ONLY;

        SELECT @TotalCount AS TotalRecords;

    END TRY
    BEGIN CATCH
        THROW;
    END CATCH
END
