-- =============================================
-- Author:		Dennis Jayvee Patricio (ddpatricio)
-- Create date: 06/02/2025 12:00:00 AM
-- Description:	Fetch Product Summary
-- =============================================

CREATE PROCEDURE [dbo].[GetProductSummary]
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
		WITH AllPolicies AS (
		SELECT
			[ProductsId],
			[TotalPremium],
			[TotalPaid],
			[CreatedDateTime]
		FROM
			[Transaction].[IndividualPolicy]
		WHERE IsDeleted = 0

		UNION ALL

		SELECT
			[ProductsId],
			[TotalPremium],
			[TotalPaid],
			[CreatedDateTime]
		FROM
			[Transaction].[GroupPolicy]
		WHERE IsDeleted = 0

		UNION ALL

		SELECT
			[ProductsId],
			[TotalPremium],
			[TotalPaid],
			[CreatedDateTime]
		FROM
			[Transaction].[PartnerPolicy]
		WHERE IsDeleted = 0
		),
		MonthlyProductAggregates AS (
		SELECT
			ProductsId,
			DATEFROMPARTS(YEAR(CreatedDateTime), MONTH(CreatedDateTime), 1) AS MonthStart,
			COUNT(ProductsId) AS MonthlyBookings,
			SUM(TotalPremium) AS MonthlyPremium,
			SUM(TotalPaid) AS MonthlyPaid,
			MAX(CreatedDateTime) AS MonthlyLastTransaction
		FROM
			AllPolicies
		GROUP BY
			ProductsId,
			DATEFROMPARTS(YEAR(CreatedDateTime), MONTH(CreatedDateTime), 1)
		),
		LaggedProductAggregates AS (
		SELECT
			ProductsId,
			MonthStart,
			MonthlyBookings,
			MonthlyPremium,
			MonthlyPaid,
			MonthlyLastTransaction,
			LAG(MonthlyBookings, 1, 0) OVER (PARTITION BY ProductsId ORDER BY MonthStart) AS PreviousMonthBookings
		FROM
			MonthlyProductAggregates
		),
		CurrentMonthData AS (
		SELECT
			ProductsId,
			MonthStart,
			MonthlyBookings,
			MonthlyPremium,
			MonthlyPaid,
			MonthlyLastTransaction,
			PreviousMonthBookings,
			ROW_NUMBER() OVER (PARTITION BY ProductsId ORDER BY MonthStart DESC) AS Rn
		FROM
			LaggedProductAggregates
		)
		SELECT
		PC.Description AS Category,
		P.Name AS ProductName,
		P.Code AS ProductCode,
		ISNULL(CAST(CMD.MonthlyBookings AS INT), 0) AS TotalBookings,
		ISNULL(CAST(CMD.MonthlyPremium AS DECIMAL(18,2)), 0.00) AS TotalPremiums,
		ISNULL(CAST(CMD.MonthlyPaid AS DECIMAL(18,2)), 0.00) AS TotalPayments,
		CAST(CMD.MonthlyLastTransaction AS DATETIME) AS LastTransaction,
		CASE
			WHEN ISNULL(CMD.MonthlyBookings, 0) > ISNULL(CMD.PreviousMonthBookings, 0) THEN 'UP'
			WHEN ISNULL(CMD.MonthlyBookings, 0) < ISNULL(CMD.PreviousMonthBookings, 0) THEN 'DOWN'
			WHEN ISNULL(CMD.MonthlyBookings, 0) = ISNULL(CMD.PreviousMonthBookings, 0) THEN 'MIDDLE'
			ELSE 'N/A'
		END AS Trend
		FROM
		[Reference].[Products] AS P
		JOIN
		[Reference].[ProductCategory] AS PC
		ON P.ProductCategoryId = PC.Id
		LEFT JOIN CurrentMonthData AS CMD
		ON P.Id = CMD.ProductsId AND CMD.Rn = 1
		WHERE P.IsDeleted = 0
		ORDER BY
		PC.Description, P.Name;
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH
END;
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

